WITH payload AS (SELECT $archive_payload$[{"id":"8703b3f8-accb-559f-bd44-8d7b1d2ddc63","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب حضانة أوالد -عدم زواج األم وزواج األب -تخيير األوالد بعد سن السابعة بن والديهم ذكور ا أو إناث ا ما لم يكونوا معتوهن -احلضانة حق متجدد -احلكم باحلضانة ملن يختاره الولد -حضانة الصغير دون السابعة ألمه .","document_number":"34205082","case_number":"3356681","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"حضانة -طلب حضانة أوالد -عدم زواج األم وزواج األب -تخيير األوالد بعد سن السابعة بن والديهم ذكور ا أو إناث ا ما لم يكونوا معتوهن -احلضانة حق متجدد -احلكم باحلضانة ملن يختاره الولد -حضانة الصغير دون السابعة ألمه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34205082 :‬تاريخه ‪1434/5/4 :‬هـ‬\n                           ‫رقم الدعوى‪3356681:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34247032‬تاريخه‪1434/6/20 :‬هـ‬\n\n\n      ‫حضانــة ‪ -‬طلــب حضانــة أوالد ‪ -‬عــدم زواج األم وزواج األب ‪ -‬تخييــر‬\n      ‫األوالد بعــد ســن الســابعة بــن والديهــم ذكــور ًا أو إناثـ ًا مــا لــم يكونــوا‬\n      ‫معتوهــن ‪ -‬احلضانــة حــق متجــدد ‪ -‬احلكــم باحلضانــة ملــن يختــاره‬\n                                       ‫الولــد ‪ -‬حضانــة الصغيــر دون الســابعة ألمــه ‪.‬‬\n\n\n\n      ‫خيــر غالمـ ًا بــن أبيــه‬\n                               ‫‪ .1‬مــا صــح عــن النبــي صلــى اهلل عليــه وســلم أنــه ّ‬\n                                            ‫وأمــه ‪ .‬قــال الشــافعي ‪ :‬واجلاريــة مثلــه ‪.‬‬\n      ‫‪ .2‬قــال أهــل العلــم ‪ :‬فيكــون عنــد مــن اختــاره منهمــا ‪ ،‬فــإذا اختــار اآلخــر‬\n                                                                       ‫منهمــا نقــل إليــه ‪.‬‬\n      ‫‪ .3‬األصــح تخييــر األوالد بــن والديهــم ســواء كانــوا ذكــور ًا أو إناث ـ ًا‬\n      ‫إذا بلغــوا ســبع ســنني مــا لــم يكونــوا معتوهــن ‪ ،‬وهــذا مذهــب الشــافعي‬\n                                                    ‫وروايــة عــن أحمــد ـ رحمهــم اهلل ـ ‪.‬‬\n                  ‫‪ .4‬قوله صلى اهلل عليه وسلم ‪ ( :‬أنت أحق به ما لم تنكحي ) ‪.‬‬\n                                 ‫‪ .5‬املادة (‪/10/34‬هـ ) من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫حضــرت املدعيــة وادعــت علــى الغائــب عــن مجلــس احلكــم بأنهــا‬\n      ‫كانــت زوجــة لــه وقــد أجنبــت منــه خمســة أوالد األول ذكــر واملولــود‬\n\n‫‪159‬‬\n\f‫بتاريــخ ‪1418/5/9‬ه ـ والثانــي أنثــى واملولــودة بتاريــخ ‪1419/10/30‬ه ـ‬\n‫والثالــث ذكــر واملولــود بتاريــخ ‪1422/2/24‬ه ـ والرابــع ذكــر واملولــود‬\n‫بتاريــخ ‪1424/10/9‬ه ـ واخلامــس ذكــر واملولود بتاريــخ ‪1428/7/22‬هـ‬\n‫وقــد طلقهــا وهــو رجــل متــزوج وتســكن يف بيــت مســتقل وغيــر متزوجــة‬\n‫وتطلــب حضانــة أوالدهــا املذكوريــن‪ ،‬مت بعــث صــورة مصدقــة مــن‬\n‫ضبــط القضيــة إلــى مقــر ســكن املدعى عليه ومت اســتخالف احملكمة‬\n‫هنــاك ألخــذ جوابــه عــن الدعــوى بنــاء علــى املادة (‪/10/34‬ه ـ ) من نظام‬\n‫املرافعــات الشــرعية‪ ،‬حضــر املدعــى عليــه يف جلســة أخــرى وصادق على‬\n‫زواجــه مــن املــرأة وطالقهــا منــه وقــرر عــدم رغبتــه يف حضانــة املدعيــة‬\n‫ألوالدهــا ألنهــا تســكن يف بيــت مســتقل وتركــب مــع الســائقني بــدون‬\n‫محــرم‪ ،‬طلــب املدعــى عليــه حضانــة ابنتــه ألنهــا يف ســن املراهقــة وقــرر‬\n‫أنــه ال مانــع مــن تخييــر األوالد الباقــن وقــررت املــرأة أن املدعــى عليــه‬\n‫ســبق وأن أخــذ البنــت فتعرضــت لعــدة مضايقــات مــن عماتهــا وعمهــا‪،‬‬\n‫قــرر املدعــى عليــه بأنــه ال مانــع لديــه مــن بقــاء االبــن ‪ ...‬لــدى املدعيــة‬\n‫لكونــه مــا زال صغيــراً‪ ،‬متــت محاولــة اإلصــاح بــن الطرفــن وبعثهــا‬\n‫إلــى مكتــب إصــاح ذات البــن واصطلحــوا علــى تخييــر األوالد مــا عــدا‬\n‫البنــت وعمرهــا أربعــة عشــر عامـ ًا فــكل أبــدى طلبــه حلضانتهــا ‪-‬قــررت‬\n‫املدعيــة بأنــه ســبق وأن قــام املدعــى عليــه بتهديــد ابنتــه وضربهــا ضربـ ًا‬\n‫شــديد ًا وأنكــر ذلــك املدعــى عليــه وبالكتابــة لهيئــة التحقيــق واالدعــاء‬\n‫العــام تبــن أن الدعــوى مقامــة مــن بنــت املدعيــة ضــد والدهــا ومت حفــظ‬\n‫الدعــوى‪ ،‬ظهــر للقاضــي مــن حــال املدعيــة واملدعــى عليــه أنــه متقــارب‪،‬‬\n‫احلكــم بتخييــر األوالد وهــم ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬فاختــار ‪ ...‬و‪ ...‬والدتهــم و‪...‬‬\n‫و‪ ...‬اختــارا والدهــم‪ ،‬احلكــم بحضانــة ‪ ...‬للمدعيــة لكونهــا لــم تتــزوج‬\n\n\n                                                                                        ‫‪160‬‬\n\f      ‫ولــم يبلــغ الســن الســابعة وكونــه صغيــراً‪ ،‬قــرر املدعــى عليــه اعتراضــه‬\n           ‫علــى احلكــم بالئحــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وصلــى اهلل وســلم علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ .......‬القاضــي يف احملكمــة العامــة بحائــل وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بحائــل برقــم ‪3356681‬‬\n      ‫وتاريــخ ‪ 1433/01/22‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33145856‬وتاريخ‬\n      ‫‪ 1433/01/22‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1433/03/15‬ه ـ فتحــت‬\n      ‫اجللســة الســاعة التاســعة وفيهــا حضــرت ‪ .......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .......‬املعــرف بهــا مــن قبــل ‪ .......‬ســجل مدنــي‬\n      ‫رقــم ‪ .......‬وادعــت علــى الغائــب عــن مجلــس احلكــم ‪ .......‬ســجل مدنــي‬\n      ‫رقــم ‪ .......‬قائلــة يف دعواهــا عليــه إنــه قبــل خمســة عشــر عامـ ًا تزوجنــي‬\n      ‫املدعــى عليــه ‪ .......‬وقــد أجنبــت لــه خمســة أوالد األول ابــن اســمه‬\n      ‫‪ .......‬املولــود بتاريــخ ‪1418/5/9‬ه ـ والثانيــة بنــت اســمها ‪ .......‬املولــودة‬\n      ‫بتاريــخ ‪1419/10/30‬ه ـ والثالــث ابــن اســمه ‪ .......‬املولــود بتاريــخ‬\n      ‫‪1422/2/24‬ه ـ والرابــع ابــن اســمه ‪ .......‬املولــود بتاريــخ ‪1424/10/9‬هـ‬\n      ‫واخلامــس ابــن اســمه ‪ .......‬املولــود بتاريــخ ‪1428/7/22‬ه ـ وقــد طلقنــي‬\n      ‫املدعــى عليــه مبوجــب صــك الطــاق الصــادر مــن محكمة حفــر الباطن‬\n      ‫برقــم ‪ .......‬يف ‪1432/1/29‬ه ـ كمــا أنــه أخــذ عنــده بعــض األوالد‬\n      ‫وهــو رجــل متــزوج وأنــا لــم أتــزوج حتــى اآلن وأســكن يف بيــت مســتقل‬\n      ‫لــذا أطلــب ســؤال املدعــى عليــه واحلكــم لــي بحضانــة األوالد وإلزامــه‬\n      ‫بتســليمي إياهــم علم ـ ًا أن املدعــى عليــه يعمــل يف اجليــش يف مدينةامللــك‬\n\n‫‪161‬‬\n\f‫ـاء علــى‬\n       ‫خالــد العســكرية ويحمــل جــوال رقــم ‪ .......‬هــذه دعــواي وبنـ ً‬\n‫املــادة ‪/10/34‬ه ـ مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة‬\n‫فقــد قــررت بعــث صــورة مــن ضبــط الدعــوى إلــى احملكمــة العامــة‬\n‫بحفــر الباطــن إلحضــار املدعــى عليــه وعــرض دعــوى املدعيــة عليــه‬\n‫وســماع جوابــه وقــد اســتخلفت فضيلــة رئيــس محكمــة حفــر الباطــن أو‬\n‫مــن ينيبــه مــن قضــاة احملكمــة يف ذلــك ورفعــت اجللســة إلــى يــوم األحــد‬\n‫املوافــق ‪1433/7/6‬ه ـ الســاعة التاســعة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/03/15‬هـ‬\n‫احلمــد هلل وحــده وبعــد ثــم يف يــوم األحــد املوافــق‪ 1433/07/13‬ه ـ‬\n‫فتحــت اجللســة الثانيــة الســاعة التاســعة والنصــف بحضــور املدعيــة‬\n‫بصحبــة أخيهــا ‪ .......‬ســجل مدنــي رقــم ‪ .......‬ولــم يردنــا مــن محكمــة‬\n‫حفــر الباطــن جــواب املدعــى عليــه عــن هــذه الدعــوى حتــى االن ويف‬\n‫هــذه اجللســة حضــر املدعــى عليــه ‪ .......‬ســجل مدنــي رقــم ‪ .......‬وقــرر‬\n‫قائــا إننــي قــد حضــرت مــن حفــر الباطــن بنفســي للجــواب علــى دعــوى‬\n‫املدعيــة وقــد جــرى عــرض دعــوى املدعيــة علــى املدعــى عليــه وســألناه‬\n‫اجلــواب فأجــاب قائــا مــا ذكرتــه املدعيــة مــن الــزواج واالوالد ثــم‬\n‫الطــاق فهــذا كلــه صحيــح ولكــن الطــاق برغبتهــا ومــا ذكرتــه‬\n‫أننــي أخــذت بعــض االوالد فهــذا صحيــح أيضــا وأمــا احلضانــة فإننــي‬\n‫ال أوافــق علــى حضانتهــا لــأوالد النهــا تســكن يف بيــت مســتقل وليــس‬\n‫عندهــا أحــد وتذهــب مــع ســائق وجتــيء مــع ســائق آخــر وليــس عندهــا‬\n‫محــرم يف البيــت إال أبنــي ‪ .......‬وعمــره خمســة عشــر عامــا ويذهــب إلــى‬\n‫املدرســة وجتلــس لوحدهــا يف البيــت أربــع وعشــرين ســاعة وكل يــوم‬\n‫لهــا ســائق وأنــا االن اطلــب حضانــة أبنتــي ‪ .......‬النهــا يف ســن املراهقــة‬\n\n\n                                                                                     ‫‪162‬‬\n\f      ‫وأمــا االبنــاء فمــن شــاء منهــم أن يجلــس عنــدي أو عنــد والدتــه فهــو‬\n      ‫باخليــار وإذا جلســوا عنــدي فإنــا مســتعد بزيارتهــم المهــم وأمــا البنــت‬\n      ‫فليــس للمدعيــة إال الزيــارة هــذه اجابتــي وعنــد ســماع املدعيــة إجابــة‬\n      ‫املدعــى عليــه قــررت قائلــة أوال قولــه إننــي أذهــب مــع الســائقني فهــذا‬\n      ‫غيــر صحيــح الننــي ال أذهــب إال مــع محارمــي وقــد اتصــل هــذا احلاضــر‬\n      ‫علــى أوالد أختــي الذيــن كانــوا يوصلوننــي يهددهــم ويطلــب منهــم عــدم‬\n      ‫الذهــاب بــي وقــال يف حقــي كالمــا غيــر الئــق وأمــا طلبــه حضانــة البنــت‬\n      ‫فــا أوافــق علــى ذلــك الن ابنتــي يف ســن املراهقــة وســبق أن أخذهــا‬\n      ‫فأجلســها عنــد والدتــه فتعرضــت إلــى مضايقــات وضــرب مــن عماتهــا‬\n      ‫ومــن عمهــا‪ ،‬ووالدهــا هــذا احلاضــر ال يعلــم عــن شــئ ألنــه يعمــل يف‬\n      ‫حفــر الباطــن وعندمــا كانــت ابنتــي عنــده تذهــب للمدرســة وجتــئ مــع‬\n      ‫الســائق وأمــا االبنــاء فــا مانــع مــن تخييــر الكبــار منهــم وهــم ‪ .......‬و‬\n      ‫‪ .......‬و ‪ .......‬فــإذا أختارونــي أو أختــاروا والدهــم فأنــا أوافــق علــى ذلــك‬\n      ‫وأمــا االبــن ‪ .......‬فهــو صغيــر اآلن واطلــب حضانتــه عنــدي هــذا مــا لــدي‬\n      ‫وعنــد ســماع املدعــى عليــه ذلــك قرر قائال ال مانــع من أن تكون حضانة‬\n      ‫االبــن الصغيــر ‪ .......‬عنــد والدتــه وأن يخييــر باقــي االبنــاء وأمــا البنــت‬\n      ‫فــا أوافــق علــى حضانــة املدعيــة لهــا النهــا أنكــرت الســائقني واقــرت‬\n      ‫بــأن اوالد أختهــا هــم الذيــن يذهبــون بهــا واوالد أختهــا ليســوا محارمــا‬\n      ‫البنتــي وأمــا قــول املدعيــة أن ابنتــي عندمــا كانــت عنــدي تذهــب مــع‬\n      ‫الســائق فهــذا غيــر صحيــح والصحيــح أنهــا تذهــب مــع عمهــا وهــو أخــي‬\n      ‫ومحــرم لهــا هــذا مــا لــدي ولــذا فقــد افهمــت املدعيــة بأحضــار ابنتهــا‬\n      ‫واملدعــى عليــه باحضــار االبنــاء يف اجللســة القادمــة يف يــوم االربعــاء‬\n      ‫املوافــق ‪1433/8/28‬ه ـ الســاعة التاســعة وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n\n\n‫‪163‬‬\n\f‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/07/13‬هـ‬\n‫احلمــد هلل وحــده ثــم يف يــوم األحــد املوافــق‪ 1433/10/29‬ه ـ فتحــت‬\n‫اجللســة الثالثــة الســاعة ‪ 08 : 00‬وفيهــا حضــرت املدعيــة برفقــه املعــرف‬\n‫لهــا كمــا حضــر املدعــى عليــه وبعــد مداولة بــن الطرفني قررت إحالة‬\n‫املعاملــة إلــى مكتــب إصــاح ذات البــن بهــذه احملكمــة حملاولة الصلح‬\n‫بــن الطرفــن ولــذا رفعــت اجللســة الــى يــوم الســبت ‪1433/11/28‬هـ ـ‬\n‫الســاعة التاســعة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/10/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ثــم يف يــوم الســبت املوافــق‪ 1434/02/02‬ه ـ‬\n‫فتحــت اجللســة الرابعــة الســاعة ‪ 09 : 00‬وفيهــا حضــرت املدعيــة برفقــه‬\n‫املعرف لها ‪ .......‬مبوجب السجل املدني رقم ‪ .......‬وهو مضاف بكرت‬\n‫عائلــة والــده كمــا حضــر املدعــى عليــه وحيث عــادت املعاملة من رئيس‬\n‫هيئــة اخلبــراء واصــاح ذات البــن برقــم ‪ .......‬يف ‪1434/12/22‬هـ وهذا‬\n‫نصــه ( ففــي هــذا اليــوم االربعــاء ‪1434/12/22‬ه ـ حضــرت املدعيــة‬\n‫‪ .......‬وحضــر حلضورهــا املدعــى عليــه ‪ .......‬وهــو زوجهــا الســابق‬\n‫بحضــور إبنيهمــا ‪ .......‬وذلــك بشــأن مطالبــة املــرأة بحضانــة أوالدهــا‬\n‫منــه وقــد حاولنــا الصلــح بينهمــا وأصطلحــا علــى أن يكــون االوالد‬\n‫عنــد مــن يرغبــون مــن االبويــن وأنحصــر خالفهمــا علــى البنــت ‪.......‬‬\n‫وذلــك الن عمرهــا االن أربعــة عشــر ســنة ويطالــب االب أن تكــون أبنتــه‬\n‫عنــده لوجــود والدتــه وكذلــك عمهــا ‪ .......‬يف بيتــي الواقــع بحــي ‪.......‬‬\n‫وأمــا والــدة البنــت فتقــول أن والــد البنــت ‪ .......‬يعمــل يف منطقــة احلفــر‬\n‫عســكري وال يحضــر ســواء يف أجــازة نهايــة كل أســبوع أن لــم يكــن‬\n‫مجــازا رســميا واســتعد والــد البنــت بتأمــن املواصــات البنتــه ذهابــا‬\n\n\n                                                                                     ‫‪164‬‬\n\f      ‫وعــودة مــن املدرســة مــع زوجتــه اجلديــدة التــي تعمــل بالقــرب مــن مدرســة‬\n      ‫أبنتــه وأن الســائق معــه زوجتــه وأن لــم يتيســر الســائق وزوجتــه فإنــه يقــوم‬\n      ‫عمهــا ‪ .......‬بأيصالهــا ولكــن والــدة البنــت أصــرت بقولهــا أن أبنــي‬\n      ‫‪ .......‬وهــو أبنــه أيضــا واخ البنــت الشــقيق وأنهــا مســتعدة بأخطــار ســائق‬\n      ‫يرافقــه أبنهــا ‪ .......‬ويقــوم بأيصــال البنــت ذهابــا وعــودة مــن املدرســة‬\n      ‫أو مــا حتتاجــه مــن مســتلزمات مــن الســوق أو مراجعــة املستشــفيات أو‬\n      ‫املســتوصفات وحيــث أنــه يقــع بيتهــا أيضــا يف حــي ‪ .......‬وليــس بعيــدا‬\n      ‫عــن املدرســة فأننــي أيضــا هكــذا تقــول املــرأة ‪ .......‬أنهــا ليــس لديهــا‬\n      ‫مانــع مــن ايصــال البنــت موقــع اخلــاف مــن بيتهــا إلــى املدرســة مــن قبــل‬\n      ‫والدهــا أو عمهــا بشــرط أن تكــون لــدي اقامتهــا هكــذا قالــت هــذا مــا‬\n      ‫مت لدينــا بحضورهمــا وهمــا بحالتهمــا املعتبــرة شــرعا وأفهمناهمــا أن‬\n      ‫مســألة حســم اقامــة احلضانــة للبنــت البالغــة لــدى فضيلــة ناظــر القضيــة)‬\n      ‫انتهــى نصــه وقــد جــرى تالوتــه علــى الطرفــن فقــررت املدعيــة قائلــة أن‬\n      ‫املدعــى عليــه ســبق أن اخــذ البنــت ‪ .......‬عنــده يف آخــر شــهر شــعبان‬\n      ‫لعــام ‪1433‬ه ـ وقــد تعهــد لديكــم برعايتهــا واحملافظــة عليهــا وارجاعهــا‬\n      ‫إلــي بعــد الزيــارة ولكنــه تأخــر يف ارجاعهــا كمــا قــام بضربهــا ضربــا‬\n      ‫مبرحــا واخــرج عليهــا الســكني يهددهــا ولــم يفكهــا منــه إال ابــن‬\n      ‫اخــت املدعــى عليــه واســمه ‪ .......‬ويوجــد معاملــة بهــذا اخلصــوص يف‬\n      ‫شــرطة ‪ .......‬اطلــب الكتابــة إليهــم حتــى يفيدوكــم مبــا حصــل هــذا‬\n      ‫مــا لــدي وعنــد ســماع املدعــى عليــه ذلــك قــرر قائــا أن ابنتــي ‪.......‬‬\n      ‫جلســت عنــدي قرابــة عشــرة ايــام وامــا قولهــا أننــي اضربهــا وهددتهــا‬\n      ‫بالســكني فهــذا غيــر صحيــح وان كيدهــن كيـ ًـد عظيــم وحقيقــة‬\n      ‫االمــر أن املدعيــه تقدمــت بشــكوى يف مركــز شــرطة ‪ .......‬بحائــل‬\n\n\n‫‪165‬‬\n\f‫تدعــي أننــي ضربــت البنــت ‪ .......‬وهددتهــا وقــد انتهــى هــذا املوضــوع‬\n‫وأخــذت مــن الشــرطة مبوجــب تعميــم كــف بحــث عــن شــخص برقــم‬\n‫‪ .......‬يف ‪1433/11/21‬ه ـ ويتضمــن انتهــاء املوضــوع مــن قبــل مركــز‬\n‫شــرطة ‪ .......‬وارفــق لكــم صــورة مــن هــذا التعميــم وقــد ارفــق املدعــى‬\n‫عليــه صــورة التعميــم وحيــث االمــر مــا ذكــر فقــد قــررت الكتابــة إلــى‬\n‫مركــز شــرطة ‪ .......‬لالفــادة عــن مــا لديهــم حيــال هــذه الشــكوى وقبــل‬\n‫رفــع اجللســة طلــب املدعــى عليــه االذن لــه بالــكالم ثــم قــال أن املدعيــه‬\n‫ســبق أن تعهــدت لديكــم بإنهــا اذا ارادت الســفر أن تضــع بنتــي ‪.......‬‬\n‫عنــدي ولكــن املدعيــه حجــت هــذه الســنة وتركــت البنــت عنــد ابــن‬\n‫عمهــا ‪ .......‬وعنــده ســتة أوالد ليســوا محارمــا لهــا اطلــب كتابــة هــذا‬\n‫الــكالم وعنــد ســماع املدعيــه ذلــك قــررت قائلــة أوال هــذا الــكالم‬\n‫غيــر صحيــح فعندمــا حجيــت وضعــت ابنتــي ‪ .......‬عنــد والدتــي ثانيــا لــم‬\n‫اضــع البنــت عنــد والدهــا بعدمــا حصــل منــه املشــكلة التــي يف مركــز‬\n‫شــرطة ‪ .......‬واطلــب الكتابــة لهــم بذلــك ورفعــت اجللســة للكتابــة‬\n‫ملركــز شــرطة ‪ .......‬لالفــادة مبــا لديهــم ومت حتديــد موعــد اجللســة‬\n‫يف يــوم االثنــن املوافــق ‪1434/3/2‬ه ـ الســاعة التاســعة وعليــه جــرى‬\n‫التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/02‬ه ـ‬\n‫احلمــد هلل وحــده ثــم يف يــوم اإلثنــن املوافق‪1434/03/02‬ه ـ فتحــت‬\n‫اجللســة اخلامســة الســاعة التاســعة بحضــور املدعيــة برفقــة املعــرف بهــا‬\n‫كمــا حضــر املدعــى عليــه وقــد عــاد اجلــواب مــن مركــز شــرطة ‪.......‬‬\n‫برقــم ‪ .......‬يف ‪1434/02/11‬هـ ـ املتضمــن مــا نصــه ( عليــه نفيدكــم‬\n‫أنــه يوجــد لدينــا دعــوى مــن املواطنــه ‪ .......‬ضــد والدهــا ‪ .......‬بانــه يقــوم‬\n\n\n                                                                                          ‫‪166‬‬\n\f      ‫بضربهــا وتهديدهــا بالقتــل وقــد مت احالــة كامــل أوراق املذكــورة الــى‬\n      ‫هيئــة التحقيــق واإلدعــاء العــام رقــم ‪ .......‬يف ‪ 1434/02/02‬ه ــ) انتهــى‬\n      ‫نصــه ثــم قــررت املدعيــة قائلــة اطلــب الكتابــة الــى هيئــة التحقيــق‬\n      ‫واالدعــاء العــام لإلفــادة عــن هــذه الشــكوى و رفعــت اجللســة للكتابــة‬\n      ‫الــى هيئــة التحقيــق واالدعــاء العــام لإلفــادة مبــا لديهــم ولــذا رفعــت‬\n      ‫اجللســة الــى يــوم الســبت املوافــق ‪1434/05/04‬هـ ـ الســاعة التاســعة‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                             ‫وســلم ‪ .‬حــرر يف ‪ 1434/03/02‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم يف يــوم الســبت املوافــق‪ 1434/05/04‬ه ـ‬\n      ‫فتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــرت املدعيــة بصحبــة ابنهــا‬\n      ‫‪ .......‬كمــا حضــر املدعــى عليــه وقــد وردت االفــادة بخطــاب رئيــس فــرع‬\n      ‫هئيــة التحقيــق واالدعــاء العــام بحائــل رقــم ‪ .......‬يف ‪1434/3/16‬ه ـ‬\n      ‫واملتضمــن إنــه صــدر يف الدعــوى أمــر حفــظ حيــث مت ابــاغ صاحــب‬\n      ‫احلــق اخلــاص بأمــر احلفــظ وافهامــه بــأن لــه حــق اقامــة دعــوى مباشــرة‬\n      ‫أمــام احملكمــة املختصــة ) انتهــى نصــه وقــد جــرى عرضــه علــى‬\n      ‫الطرفــن ومحاولــة الصلــح بينهمــا فأصــر كل واحــد منهمــا علــى أقواله‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث اتفــق الطرفــان علــى‬\n      ‫أن يكــون األبنــاء ‪ .......‬و ‪ .......‬و ‪ .......‬عنــد مــن يختــارون مــن والديهــم‬\n      ‫كمــا وافــق املدعــى عليــه ‪ .......‬بــأن تكــون حضانــة الطفــل ‪ .......‬عنــد‬\n      ‫والدتــه وحيــث أن احلضانــة حــق متجــدد كمــا نــص علــى ذلــك أهــل العلم‬\n      ‫وقــد ظهــر لنــا مــن حــال املدعيــة واملدعــى عليــه أنــه متقــارب وحيــث أن‬\n      ‫الراجــح لــدي تخييــر األوالد بــن والديهــم ســواء كانــوا ذكــورا أو إناثــا‬\n      ‫إذا بلغــوا ســبع ســنني ولــم يكونــوا معتوهــن وهــذا مذهــب الشــافعي‬\n\n\n‫‪167‬‬\n\f‫وروايــة عــن أحمــد رحمهمــا اهلل ملــا صــح عــن النبــي صلــى اهلل عليــه‬\n‫وســلم أنــه خيــر غالمــا بــن أبيــه وأمــه قــال الشــافعي واجلاريــة مثلــه قــال‬\n‫أهــل العلــم فيكــون عنــد مــن اختــاره منهمــا فــإذا اختــار اآلخــر منهمــا‬\n‫نقــل إليــه وهكــذا أبــدا لذلــك كلــه فقــد حكمــت بتخييــر األوالد وهــم‬\n‫‪ .......‬و ‪ .......‬و ‪ .......‬و ‪ .......‬بــن والديهــم فيكــون الواحــد منهــم عنــد‬\n‫مــن اختــاره مــن والــده أو والدتــه وقــد حضــر يف هــذه اجللســة األوالد‬\n‫كل مــن ‪ .......‬و ‪ .......‬و ‪ .......‬و ‪ .......‬فأفهمــت كل واحــد منهــم بــأن‬\n‫يختــار أحــد والديــه فقــرر األول ‪ .......‬والثانيــة ‪ .......‬بأنهمــا يختــاران‬\n‫والدتهمــا ‪ .......‬كمــا قــرر ‪ .......‬و ‪ .......‬بأنهمــا يختــاران والدهمــا وأمــا‬\n‫االبــن ‪ .......‬فلــم يبلــغ ســبع ســنوات ولقــول النبــي صلــى اهلل عليــه وســلم‬\n‫«أنتــي أحــق بــه مــا لــم تنكحــي» فقــد حكمــت بــأن تكــون حضانتــه‬\n‫عنــد والدتــه حتــى يبلــغ ســبع ســنوات ثــم يخيــر بــن والديــه ومبــا تقــدم‬\n‫حكمــت وبعــرض احلكــم علــى الطرفــن قــررت املدعيــة القناعــة أمــا‬\n‫املدعــى عليــه فقــرر عــدم القناعــة وطلــب متكينــه مــن تقــدمي الئحــة‬\n‫اعتراضيــة فأجبتــه لطلبــه وســوف يتــم تســليمه نســخة مــن الصــك بعــد‬\n‫التوقيــع يف هــذا اليــوم إن شــاء اهلل كمــا أفهمتــه بــأن عليه تقدمي الئحته‬\n‫االعتراضيــة خــال ثالثــن يومــا مــن تاريــخ هــذا اليــوم وإذا مضــت املــدة‬\n‫ولــم يقــدم الئحتــه فيكتســب احلكــم القطعيــة ففهــم ذلــك وعليــه جــرى‬\n‫التوقيــع واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم حــرر يف ‪1434/5/4‬ه ــوباهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/04‬ه ـ‬\n‫احلمــد هلل رب العاملــن ‪ ،‬والصــاة والســام علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه أجمعــن ‪ ،‬أمــا بعــد ‪ :‬فقــد اطلعنــا نحــن قضــاة دائــرة األحــوال‬\n\n\n                                                                                        ‫‪168‬‬\n\f      ‫الشــخصية مبحكمــة االســتئناف مبنطقــة حائــل علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بحائــل املســاعد رفــق كتابــه‬\n      ‫رقــم (‪ )33145856‬وتاريــخ ‪1434/6/10‬ه ـ ‪ ،‬واملقيــدة لدينــا برقــم‬\n      ‫(‪ )33145856‬وتاريــخ ‪1434/6/11‬ه ـ ‪ ،‬املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة الشــيخ‪ ....... /‬القاضــي باحملكمــة العامــة بحائــل برقــم‬\n      ‫(‪ )34205082‬وتاريــخ ‪1434/5/4‬ه ـ اخلــاص بدعــوى‪ ....... /‬ضــد‪/‬‬\n      ‫‪ ، .......‬وطلبهــا إلــزام املدعــى عليــه بتســليمها أوالدهــا منــه ‪ ،‬واحلكــم‬\n      ‫لهــا بحضانتهــم ‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه بــأن يكــون ‪.......‬‬\n      ‫و ‪ .......‬ولــدي املدعــى عليــه عنــد والدتهمــا املدعيــة حســب إختيارهمــا ‪،‬‬\n      ‫ويكــون ‪ .......‬و ‪ .......‬عنــد والدهمــا املدعــى عليــه حســب إختيارهمــا ‪،‬‬\n      ‫وتكــون حضانــة الطفــل ‪ .......‬عنــد والدتــه املدعيــه ؛ حتــى بلوغــه ســبع‬\n      ‫ســنني ‪ ،‬ثــم يخيــر بــن والديــه ‪ .‬وبدراســة الصــك ‪ ،‬وصــورة ضبطــه ‪،‬‬\n      ‫والالئحــة االعتراضيــة ‪ ،‬وأوراق املعاملــة ‪ ،‬قررنــا املصادقــة علــى مــا‬\n      ‫حكــم بــه فضيلتــه ؛ مــع تنبيــه فضيلتــه إلــى مــا يلــي ‪-1:‬أن علــى فضيلتــه‬\n      ‫تذكيــر الطرفــن مبقتضــى قولــه تعالــى ‪« :‬وال تنســوا الفضــل بينكــم»‪.‬‬\n      ‫وأن األوالد أمانــة يف أعناقهمــا ‪،‬وعليهمــا احملافظــة علــى هــذه األمانــة و‬\n      ‫رعايتهــا‪-2 .‬أن يكــون نســخ إعــام احلكــم بخــط مقــاس (‪ ، )18‬أو مــا‬\n      ‫يقابلــه وفق ـ ًا للتعليمــات ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                          ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪169‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":159,"source_page_end":169,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b985029e4d0d991f9a8bf17572b2a1e539c5afbb5101fadbda1ab3b937a63c6e","normalized_text_hash":"572054c3b8cfa44500727ebe7b326a0a1e66c3906220d816e44b037d0f7522b6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p159-34205082"},{"id":"78301b4a-2811-5344-8d2c-fcbaf2ea68b2","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب حضانة أوالد -عدم زواج األم -تخيير األوالد بن والديهم ذكور ا و إناث ا -اختيار األوالد لوالدتهم -احلضانة حق للمحضون -احلكم بحضانة األم ألوالدها -حضانة من جتاوز","document_number":"34172423","case_number":"3417964","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض وبتكليف منه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/25","year":"1434","subject":"حضانة -طلب حضانة أوالد -عدم زواج األم -تخيير األوالد بن والديهم ذكور ا و إناث ا -اختيار األوالد لوالدتهم -احلضانة حق للمحضون -احلكم بحضانة األم ألوالدها -حضانة من جتاوز","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34172423 :‬تاريخه ‪1434/3/25 :‬هـ‬\n                     ‫رقم الدعوى ‪3417964:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34227322‬تاريخه‪1434/05/29 :‬هـ‬\n\n\n‫حضانــة ‪ -‬طلــب حضانــة أوالد ‪ -‬عــدم زواج األم ‪ -‬تخييــر األوالد بــن‬\n‫والديهــم ذكــور ًا و إناث ـ ًا ‪ -‬اختيــار األوالد لوالدتهــم ‪ -‬احلضانــة حــق‬\n‫للمحضــون ‪ -‬احلكــم بحضانــة األم ألوالدهــا ‪ -‬حضانــة مــن جتــاوز‬\n                                                                   ‫الســابعة ‪.‬‬\n\n\n\n          ‫‪ .1‬قوله صلى اهلل عليه وسلم ‪ ( :‬أنت أحق به ما لم تنكحي ) ‪.‬‬\n‫‪ .2‬قــال ابــن القيــم يف زاد املعــاد ( ‪ ( : )473/5‬ثــم هاهنــا حصــل االجتهــاد‬\n‫يف تعيــن أحــد األبويــن ملقامهــا عنــده وأيهمــا أصلــح لهــا ‪ ،‬فمالــك وأبــو‬\n‫حنيفــة وأحمــد يف إحــدى الروايتــن عنــه عينــوا األم وهــو الصحيــح‬\n‫ا وأحمــد ـ رحمــه اهلل ـ يف املشــهور عنــه واختيــار عامــة أصحابــه‬      ‫دلي ـ ً‬\n‫عينــوا األب ‪ ،‬قــال مــن رجــح األم « قــد جــرى يف العــادة بــأن األب يتصرف‬\n‫يف املعــاش ولقــاء النــاس واألم يف خدرهــا مقصــورة يف بيتهــا ‪ ،‬فالبنــت‬\n‫عندهــا أصــون وأحفــظ بــا شــك ‪ ،‬عينهــا عليهــا دائمــا ‪ ،‬بخــاف األب‬\n‫فإنــه يف غالــب األوقــات غائــب عــن البنــت ‪ ،‬أو يف مظنــة ذلــك يجعلهــا‬\n‫عنــد أمهــا أصــون لهــا وأحفــظ ‪ ،‬وكل مفســدة يعــرض وجودهــا عنــد‬\n‫األم فإنهــا موجــودة ‪ ،‬أو أكثــر منهــا عنــد األب ‪ ،‬فإنــه إذا تركهــا يف‬\n‫البيــت وحدهــا لــم يأمــن عليهــا ‪ ،‬وإن تــرك عندهــا امرأتــه أو غيرهــا ‪،‬‬\n‫فــاألم أشــفق عليهــا وأصــون لهــا مــن األجنبيــة ‪ ،‬أيض ـ ًا هــي محتاجــة‬\n‫إلــى تعلــم مــا يصلــح للنســاء مــن الغــزل والقيــام مبصالــح البيــت ‪،‬‬\n                                                                                      ‫‪170‬‬\n\f      ‫وهــذا تقــوم بــه النســاء ال الرجــال ‪ ،‬فهــي أحــوج إلــى أمهــا لتعلمهــا مــا‬\n      ‫صلــح للمــرأة ‪ ،‬ويف دفعهــا إلــى أبيهــا تعطيــل لهــذه املصالــح ‪ ،‬وإســامها‬\n      ‫إلــى أجنبيــة تعلمهــا ذلــك وترددهــا بــن األم واألب متريــن لهــا علــى‬\n      ‫البــروز واخلــروج ‪ ،‬فمصلحــة البنــت واألم أن تكــون عنــد أمهــا ‪ ،‬وهــذا‬\n                                                  ‫القــول الــذي ال نختــار ســواه ) ‪.‬‬\n      ‫‪ .3‬جــاء يف كتــاب الفقــه اإلســامي وأدلتــه ‪ ( :‬وأمــا صاحــب احلــق‬\n      ‫يف احلضانــة فمختلــف فيــه بــن الفقهــاء ‪ ،‬فقيــل ‪ :‬إن احلضانــة حــق‬\n      ‫للحاضــن ‪ ،‬وهــو رأي احلنفيــة واملالكيــة علــى املشــهور وغيرهــم ‪ ،‬ألن‬\n      ‫لــه أن يســقط حقــه ولــو بغيــر عــوض ‪ ،‬ولــو كانــت احلضانــة لغيــره‬\n      ‫ملــا ســقطت بإســقاطه ‪ ،‬وقيــل إنهــا حــق للمحضــون فلــو أســقطها هــو‬\n      ‫ســقطت ‪ ،‬والظاهــر لــدى العلمــاء احملققــن أن احلضانــة تتعلــق بهــا‬\n      ‫ثــاث حقــوق مع ـ ًا ‪ :‬حــق احلضانــة وحــق احملضــون وحــق األب أو مــن‬\n      ‫يقــوم مقامــه ‪ ،‬فــإن أمكــن التوفيــق بــن هــذه احلقــوق وجــب املصيــر‬\n      ‫إليــه ‪ ،‬وإن تعارضــت قــدم حــق احملضــون علــى غيــره ـ وقــدم الفقهــاء‬\n      ‫احلواضــن بعضهــم علــى بعــض بحســب مصلحــة احملضــون ‪ ،‬فجعلــوا‬\n      ‫اإلنــاث أليــق باحلضانــة ‪ ،‬ألنهــم أشــفق وأهــدى إلــى التربيــة وأصبــر‬\n      ‫علــى القيــام بهــا وأشــد مالزمــة لألطفــال ثــم قدمــوا يف اجلنــس الواحــد‬\n                                                         ‫مــن كان أشــفق وأقــرب )‬\n\n\n\n      ‫حضــر املدعــي وكالــة وادعــى بقولــه أن املدعــى عليهــا كانــت‬\n      ‫زوجــة ملوكلــه‪ ،‬وقــد أجنبــت منــه أوالد ًا األول ذكــر واملولــود بتاريــخ‬\n      ‫‪1419/6/7‬ه ـ والثانــي ذكــر واملولــود بتاريــخ ‪1427/2/28‬ه ـ والثالــث‬\n\n‫‪171‬‬\n\f‫بنــت واملولــودة بتاريــخ ‪1424/5/10‬ه ـ وهــؤالء جميعـ ًا مــع املدعــى عليهــا‬\n‫ويطلــب احلكــم ملوكلــه بحضانــة أوالده املذكوريــن أعــاه‪ ،‬بعــرض‬\n‫دعــوى املدعــي وكالــة علــى املدعــى عليهــا صادقــت علــى مــا ذكــره‬\n‫املدعــي وكالــة وترفــض حضانــة املدعــي وكالــة ألوالدها‪،‬طعــن‬\n‫املدعــي وكالــة بحضانــة األم حيــث ذكــر أنهــا ال حتافــظ علــى‬\n‫الصــاة‪ ،‬كثيــرة اخلــروج مــن املنــزل‪ ،‬وقــد وضعــت أجهــزة البــث يف‬\n‫غــرف أوالدهــا ووضعــت فيــه القنــوات الفاســدة مــن أغانــي وأفــام كما‬\n‫أن املدعــى عليهــا قامــت بإحــراق ســيارة املدعــي وكالــة وقامــت بســرقة‬\n‫بعــض أغراضــه الشــخصية‪ ،‬بســؤال املدعــى عليهــا عــن هــذه االدعــاءات‬\n‫أنكرتهــا‪ ،‬بســؤال املدعــي وكالــة البينــة علــى مــا ذكــره أجــاب بــأن‬\n‫هــذه األمــور داخــل املنزل وال ميكن أن يشــهد أحــد بذلك‪،‬حضر املدعي‬\n‫وكالــة واملدعــى عليهــا أصالــة وحضــر حلضورهــم األوالد املذكــورون‬\n‫أعــاه‪ ،‬مت ســؤالهم عمــن يرغبــون البقــاء معــه فقــرروا أنهــم يرغبــون‬\n‫اإلقامــة مــع والدتهــم‪ ،‬حيــث أن والدهــم تركهــم فتــرة بــا طعــام‪ ،‬وال‬\n‫يوجــد يف بيــت والدهــم مــن يخدمهــم‪ ،‬ووالدهــم يقتــر عليهــم يف النفقــة‬\n‫وال يشــتري حاجاتهــم املدرســية‪ ،‬اختيــار األوالد البقــاء لــدى والدتهــم‪،‬‬\n‫األم أشــفق علــى أوالدهــا‪ ،‬احلكــم بــرد دعــوى املدعــي يف مطالبتــه‬\n‫بحضانــة أوالده املذكوريــن‪ ،‬قــرر املدعــي وكالــة اعتراضــه علــى‬\n‫احلكــم بالئحــة اعتراضيــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                  ‫‪172‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬املــازم القضائــي لــدى فضيلــة‬\n      ‫الشــيخ ‪ .......‬القاضــي يف احملكمــة العامــة بالريــاض وبتكليــف منــه‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالرياض‪/‬املســاعد برقــم ‪ 3417964‬وتاريــخ ‪ 1434/01/11‬ه ـ املقيــدة‬\n      ‫باحملكمة برقم ‪ 3484188‬وتاريخ ‪ 1434/01/11‬هـ ففي يوم األربعاء‬\n      ‫املوافق‪ 1434/01/28‬هـ حضر ‪ .......‬ســعودي اجلنســية مبوجب الســجل‬\n      ‫املدنــي رقــم ‪ .......‬بصفتــه وكيــا عــن والــده مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة عــدل عرقــة برقــم ‪ .......‬وتاريــخ ‪1433/04/13‬ه ـ واملخول له‬\n      ‫فيهــا حــق املرافعــة واملدافعــة واإلقــرار والصلــح وحضــرت حلضــوره ‪.......‬‬\n      ‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬املعــرف بهــا مــن قبل‬\n      ‫ابنهــا ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬وادعــى‬\n      ‫املدعــي وكالــة قائــا إن املدعــى عليهــا كانــت زوجــة ملوكلــي وقــد‬\n      ‫طلقهــا يف ‪1433/09/11‬ه ـ وقــد رزقــه اهلل منهــا بــأوالد والقصــر منهــم‬\n      ‫هم ‪ .......‬املولود يف ‪1419/06/07‬هـ و ‪ .......‬املولود يف ‪1421/02/28‬هـ‬\n      ‫و ‪ .......‬املولــودة يف ‪1424/05/10‬ه ـ وجميعهــم مــع املدعــى عليهــا‬\n      ‫وأخرجوهــم مــن منزلهــم جبــرا وبــدون علــم موكلــي وموكلــي يطلــب‬\n      ‫حضانتهــم هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليهــا مــا ذكــره‬\n      ‫املدعــي وكالــة كلــه صحيــح وأنــا أرفــض حضانــة والدهم لهــم فاألوالد‬\n      ‫خرجــوا معــي مــن تاريــخ ‪1433/08/06‬ه ـ ولــم يطلــب حضانتهــم إال بعــد‬\n      ‫أن رفعــت دعــوى النفقــة هكــذا أجابــت وبعــرض ذلــك علــى املدعــي‬\n      ‫وكالــة أجــاب قائــا موكلــي يطلــب احلضانــة لألســباب التاليــة أنهــا‬\n\n‫‪173‬‬\n\f‫وضعــت يف البيــت أجهــزة البــث التلفزيونــي (الــدش) ووضعــت يف كل‬\n‫غرفــة جهــاز تلفزيــون ووضــع قنــوات فاســدة مــن أغانــي وأفــام تؤثــر‬\n‫علــى تربيــة أوالده وقــد نصحهــا عــدة مــرات للتخلــص مــن هــذه األجهــزة‬\n‫أو قصرهــا علــى القنــوات املفيــدة إال أنهــا لــم ترتــدع ممــا دعــاه إلتــاف‬\n‫هــذه األجهــزة والتخلــص منهــا كمــا أن املدعــى عليهــا كثيــرة الســهر‬\n‫خــارج البيــت بــدون إذن موكلــي وال تعــود إال يف ســاعات الفجــر األولــى‬\n‫ثــم تنــام طيلــة النهــار فــا تقــوم بواجباتهــا معــي كمــا أنهــا ال حتــرص‬\n‫علــى أداء الصــاة يف أوقاتهــا وال حتــرص أوالدهــا علــى الصــاة كمــا‬\n‫أنــه يوجــد لديهــا ســت جــواالت حيــث أنهــا كثيــرة اإلغــاق علــى نفســها‬\n‫يف غرفتهــا والتحــدث بهــذه اجلــواالت واملدعــى عليهــا تتلفــظ بألفــاظ‬\n‫فاحشــة ممــا جــرأ ابنهــا علــى ضربهــا كمــا أنهــا حتــرض أوالدهــا‬\n‫علــى كــره إخوانهــم مــن زوجتــي األخــرى ووصــل األمــر إلــى أن اتهمــت‬\n‫أحــد أوالدي بأنــه يتحــرش بأخيــه منهــا والقضيــة منظــورة لــدى اجلهــات‬\n‫املختصــة كمــا أن املدعــى عليهــا دخلــت منــزل موكلــي بعــد طالقــه لهــا‬\n‫وقامــت بإحــراق الســيارة مبــادة األســيد وكســر زجــاج الســيارات وأخــذ‬\n‫مســدس خــاص مبوكلــي وجوالــه وســيف يخصــه وبطاقــة أحــوال عائــدة‬\n‫لــه وبطاقــة صــراف عائــدة لــه وبعــد محــاوالت قــام أخــي ‪ .......‬بإعــادة‬\n‫اجلــوال وبطاقــة األحــوال وســلمت اســتمارة الســيارة جلارنــا وســلمها‬\n‫ملوكلــي والقضيــة لــدى الشــرطة هكــذا ذكــر وبعــرض ذلــك علــى‬\n‫املدعــى عليهــا قالــت مــا ذكــره املدعــي وكالــة كلــه ادعاءاتــك غيــر‬\n‫صحيحــة هكــذا ذكــرت وبســؤال املدعــي وكالــة ألديــك بينــة علــى‬\n‫مــا ورد يف ادعــاءات فقــال مــا ذكــر مــن أمــور أغلبهــا داخــل املنــزل وال‬\n‫ميكــن أن يشــهد أحــد بذلــك وأمــا قضيــة الســرقة فهــي لــدى الشــرطة‬\n\n\n                                                                                    ‫‪174‬‬\n\f      ‫هكــذا ذكــر بعــد ذلــك أفهمــت املدعــى عليهــا بإحضــار جميــع األوالد‬\n      ‫يف اجللســة القادمــة احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف‬\n      ‫احملكمــة العامــة بالريــاض يف يــوم األربعــاء املوافــق‪ 1434/03/25‬ه ـ‬\n      ‫حضــر املدعــي وكالــة و املدعــى عليهــا كمــا حضــر األوالد الثالثــة‬\n      ‫‪ .......‬و ‪ .......‬و ‪ .......‬وجــرى ســؤالهم عمــن يرغبــون البقــاء معــه فقــال‬\n      ‫‪ .......‬أنــا أرغــب البقــاء مــع والدتــي حيــث أننــي وبقيــة إخوانــي جلســنا‬\n      ‫يف منــزل والــدي فتــرة بــدون طعــام صالــح وال يوجــد مــن يخدمنــا يف‬\n      ‫اعــداد الطعــام أو تنظيــف املالبــس كمــا أن والــدي حفظــه اهلل مقتــر‬\n      ‫يف النفقــة وال يشــتر احتياجاتنــا الدراســية وإمنــا والدتــي هــي التــي تقــوم‬\n      ‫بذلــك كمــا أفــاد ‪ .......‬بقولــه أنــا أرغــب يف والدتــي واســتدل بقولــه‬\n      ‫صلــى اهلل عليــه وســلم للصحابــي الــذي ســأله عــن أحــق النــاس بصحبتــه‬\n                                                   ‫( أمــك ثــم أمــك ثــم أمــك ثــم أبــوك )‬\n      ‫كمــا أفــادت ‪ .......‬بأنهــا ترغــب يف والدتهــا حيــث أنهــا دائمــا معهــا وال‬\n      ‫ميكــن أن تكــون مــع غيرهــا بعــد ذلــك جــرى ســؤال املدعــي وكالــة‬\n      ‫عمــن ســيرعى األوالد فقــال سيســكنون مــع والــدي يف منزلــه الــذي‬\n      ‫بــه ثــاث أخــوات أكبرهــن عمرهــا ‪ 25‬ســنة وأصغرهــن ‪ 13‬ســنة مــع‬\n      ‫وجــود ثالثــة أوالد ووالــدي غيــر متــزوج هكــذا ذكــر وبعــرض ذلــك‬\n      ‫علــى املدعيــة قالــت مــا ذكــره املدعــي وكالــة كلــه غيــر صحيــح وأنــا‬\n      ‫غيــر متزوجــة وأســتطيع أن أرعــى أوالدي وأطلــب احلكــم بحضانتهــم لي‬\n      ‫كمــا أنــه قــد حكــم بالنفقــة هكــذا ذكــرت فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة ومبــا أن املدعــي وكالــة ال بينــة لديــه علــى مــا دفــع بــه‬\n      ‫مــن عــدم صالحيــة املدعــى عليهــا حلضانــة أوالدهــا ومبــا أن األوالد قــد‬\n      ‫اختــاروا والدتهــم ومبــا أن احلاضنــه حــق للمحضــون مــع مراعــاة احلاضــن‬\n\n\n‫‪175‬‬\n\f‫ومبــا أنــه ال خــاف بــن الفقهــاء يف أحقيــة األم حلضانــة أوالدهــا جــاء‬\n‫يف الفقــه اإلســامي وأدلتــه (وأمــا صاحــب احلــق يف احلضانــة فمختلــف‬\n‫فيــه بــن الفقهــاء فقيــل أن احلضانــة حــق للحاضــن وهــو رأي احلنفيــة‬\n‫واملالكيــة علــى املشــهور وغيرهــم ألن لــه أن يســقط حقــه ولــو بغيــر‬\n‫عــوض ولــو كانــت احلضانــة حق ـ ًا لغيــره ملــا ســقطت بإســقاطه وقيــل‬\n‫إنهــا حــق للمحضــون فلــو أســقطها هــو ســقطت والظاهــر لــدى العلمــاء‬\n‫احملققــن أن احلضانــة تتعلــق بهــا ثــاث حقــوق معــا حــق احلضانــة وحــق‬\n‫احملضــون وحــق األب أو مــن يقــوم مقامــه فــإن أمكــن التوفيــق بــن‬\n‫هــذه احلقــوق وجــب املصيــر إليــه وإن تعارضــت قــدم حــق احملضــون علــى‬\n‫غيــره‪ ....‬وقــدم الفقهــاء احلواضــن بعضهــم علــى بعــض بحســب مصلحــة‬\n‫احملضــون فجعلــوا اإلنــاث أليــق باحلضانــة ألنهــم أشــفق وأهــدى إلــى‬\n‫التربيــة وأصبــر علــى القيــام بهــا وأشــد مالزمــة لألطفــال ثــم قدمــوا يف‬\n                                 ‫اجلنــس الواحــد مــن كان أشــفق وأقــرب)‪.‬‬\n‫وقــد رجــح ابــن القيــم رحمــه اهلل تعالــى أن احلضانــة حــق للمحضــون‬\n‫والنظــر فيــه للمصلحــة وانتصــر لهــذا القــول فجــاء يف زاد املعــاد (ثــم‬\n‫هاهنــا حصــل االجتهــاد يف تعيــن أحــد األبويــن ملقامهــا عنــده وأيهمــا‬\n‫أصلــح لهــا فمالــك وأبــو حنيفــة وأحمــد يف إحــدى الروايتــن عنــه عينــوا‬\n‫ا وأحمــد رحمــه اهلل يف املشــهور عنــه واختيــار‬  ‫األم وهــو الصحيــح دلي ـ ً‬\n‫عامــة أصحابــه عينــوا األب قــال مــن رجــح األم قــد جــرى يف العــادة بــأن‬\n‫األب يتصــرف يف املعــاش ولقــاء النــاس واألم يف خدرهــا مقصــورة يف‬\n‫بيتهــا فالبنــت عندهــا أصــون وأحفــظ بــا شــك عينهــا عليهــا دائمــا‬\n‫بخــاف األب فإنــه يف غالــب األوقــات غائــب عــن البنــت أو يف مظنــة ذلك‬\n‫فجعلهــا عنــد أمهــا أصــون لهــا وأحفــظ وكل مفســدة يعــرض وجودهــا‬\n\n\n                                                                                   ‫‪176‬‬\n\f      ‫عنــد األم فإنهــا موجــودة أو أكثــر منهــا عنــد األب فإنــه إذا تركهــا‬\n      ‫يف البيــت وحدهــا لــم يأمــن عليهــا وإن تــرك عندهــا امرأتــه أو غيرهــا‬\n      ‫فــاألم أشــفق عليهــا وأصــون لهــا مــن األجنبيــة وأيضـ ًا هــي محتاجــة إلــى‬\n      ‫تعلــم مــا يصلــح النســاء مــن الغــزل والقيــام مبصالــح البيــت وهــذا تقــوم‬\n      ‫بــه النســاء ال الرجــال فهــي أحــوج إلــى أمهــا لتعلمهــا مــا صلــح للمــرأة ويف‬\n      ‫دفعهــا إلــى أبيهــا تعطيــل لهــذه املصالــح وإســامها إلــى أجنبيــة تعلمهــا‬\n      ‫ذلــك وترديدهــا بــن األم واألب متريــن لهــا علــى البــروز واخلــروج فمصلحــة‬\n      ‫البنــت واألم واألب أن تكــون عنــد أمهــا وهــذا القــول هــو الــذي ال نختــار‬\n      ‫ســواه) ومبــا أن املدعــي وكالــة قــرر أن األوالد ســيكونون مــع إخوانهــم‬\n      ‫وال شــك أن األم أقــدر علــى احلضانــة والرعايــة والتربيــة مــن اإلخــوة‬\n      ‫ومصلحتهــم إمنــا هــي يف بقائهــم معهــا وال يخفــى أن األم أشــفق علــى‬\n      ‫أوالدهــا مــن أي شــخص آخــر ولقولــه صلــى اهلل عليــه وســلم ( أنــت أحــق‬\n      ‫بــه مالــم تنكحــي ) جلميــع ذلــك فقــد رددت دعــوى املدعــي يف مطالبتــه‬\n      ‫بحضانــة أوالده ‪ .......‬و ‪ .......‬و ‪ .......‬وحكمــت بحضانتهــم لوالدتهــم‬\n      ‫وبعــرض احلكــم علــى املدعــي وكالــة قــرر عــدم قناعتــه باحلكــم‬\n      ‫وطالــب بتدقيــق احلكــم واســتعد بتقــدمي الئحــة اعتراضيــة وأفهــم بأنــه‬\n      ‫لــه مــدة قدرهــا ثالثــون يــوم لتقــدمي اعتراضــه اعتبــارا مــن تاريــخ اســتالم‬\n      ‫صــورة مــن نســخة احلكــم وإذا مضــت املــدة احملــددة لالعتــراض ولــم‬\n      ‫يقــدم الئحتــه فيهــا ســقط حقــه يف االســتئناف واكتســب احلكــم‬\n      ‫القطعيــة وحــدد موعــد تســليم صــورة نســخة احلكــم هــذا اليــوم الســاعة‬\n      ‫‪ 01.45‬ومت إقفــال اجللســة الســاعة ‪ 11.00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/25‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n\n\n‫‪177‬‬\n\f‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 3417964‬وتاريــخ ‪ 1434/01/11‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 3484188‬وتاريــخ ‪ 1434/01/11‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/06/17‬ه ـ حيــث عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف وبرفقهــا القــرار املــدون علــى ظهــر الصــك واملتضمــن‬\n‫مــا نصــه ( تظهيــرات الدائــرة الثانيــة لألحــوال الشــخصة واإلنهــاءات‬\n‫مبحكمــة االســتئناف بالريــاض احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا‬\n‫علــى هــذا الصــك رقــم ‪ 34172423‬وتاريــخ ‪1434/3/25‬ه ـ الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة العامــة بالريــاض الشــيخ ‪ .......‬وأصدرنــا‬\n‫القــرار رقــم ‪ 34227322‬وتاريــخ ‪1434/5/29‬ه ـ املتضمــن املصادقــة‬\n‫باألكثريــة علــى احلكــم واهلل املوفــق قاضــي اســتئناف ‪ .......‬ختمــه‬\n‫وتوقيعــه قاضــي اســتئناف ‪ .......‬ختمــه وتوقيعــه رئيــس الدائــرة ‪.......‬‬\n‫ختمــه وتوقيعــه لــي وجهــة نظــر ) وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد برقــم ‪ 3484188‬وتاريــخ ‪1434/5/7‬ه ـ املرفــق بهــا‬\n‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ....... /‬املســجل‬\n‫برقــم‪ 34172423‬وتاريــخ ‪1434/3/25‬ه ـ اخلــاص بدعــوى ‪....... /‬‬\n‫ضــد‪ . ....... /‬يف قضيــة حضانــة‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫مباهــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة باألكثريــة املصادقــة علــي‬\n\n\n                                                                                      ‫‪178‬‬\n\f      ‫احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه‬\n                                                                              ‫وســلم ‪.‬‬\n\n\n\n\n‫‪179‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":170,"source_page_end":179,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"625364391dd04833d55aa4ab6d3ac0aaf1926b147c1ff3cfa9f85959af93e6f4","normalized_text_hash":"bc6be532edac49ec4eabebc9f8e2f3354b9386d2bb60c0fae608e1db857b6f88","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p170-34172423"},{"id":"78ee7370-8c80-5d6d-9a31-52581d592508","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب حضانة ابن -تخيير االبن البالغ من العمر سبع سنوات بن والده ووالدته -اختيار االبن لوالده -احلكم بحضانة","document_number":"34209331","case_number":"3423188","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/8","year":"1434","subject":"حضانة -طلب حضانة ابن -تخيير االبن البالغ من العمر سبع سنوات بن والده ووالدته -اختيار االبن لوالده -احلكم بحضانة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34209331 :‬تاريخه ‪1434/5/8 :‬هـ‬\n                    ‫رقم الدعوى ‪3423188:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34258198‬تاريخه‪1434/7/2:‬هـ‬\n\n\n‫حضانــة ‪ -‬طلــب حضانــة ابــن ‪ -‬تخييــر االبــن البالــغ مــن العمــر ســبع‬\n‫ســنوات بــن والــده ووالدتــه ‪ -‬اختيــار االبــن لوالــده ‪ -‬احلكــم بحضانــة‬\n                                                                  ‫والــده لــه‪.‬‬\n\n\n\n‫حديــث أبــي هريــرة ‪ -‬رضــي اهلل عنــه ‪ -‬أن امــرأة جــاءت إلــى رســول اهلل‬\n‫صلــى اهلل عليــه وســلم فقالــت ‪ :‬يــا رســول اهلل ‪ :‬إن زوجــي يريــد أن‬\n‫يذهــب بابنــي وقــد ســقاني مــن بئــر أبــي عنبــة وقــد نفعنــي ‪ ،‬قــال رســول‬\n‫اهلل صلــى اهلل عليــه وســلم ‪ :‬اســتهما عليــه ‪ ،‬فقــال زوجهــا ‪ :‬مــن يحاقنــي‬\n‫يف ولــدي ‪ ،‬فقــال النبــي صلــى اهلل عليــه وســلم ‪ ( :‬هــذا أبــوك وهــذه‬\n‫أمــك فخــذ بيــد أيهمــا شــئت فأخــذ بيــد أمــه فانطلقــت بــه ) رواه أبــو‬\n                                                               ‫داود والنســائي ‪.‬‬\n\n\n\n\n‫حضــر املدعــي وكالــة وادعــى علــى املدعــى عليــه بأنــه كان‬\n‫زوج ـ ًا ملوكلتــه وقــد طلقهــا ورزق منهــا بابــن اســمه ‪ ...‬مولــود بتاريــخ‬\n‫‪1425/11/22‬ه ـ وقــد أخــذه مــن موكلتــه ويطلــب احلكــم لــه بحضانــة‬\n‫أمــه لــه‪ ،‬صــادق املدعــى عليــه علــى زواجــه وطالقــه املدعيــة وإجنــاب‬\n‫الولــد ‪ ...‬منهــا ولــم يوافــق علــى تســليمها االبــن ألن املدعيــة تعانــي مــن‬\n\n                                                                                      ‫‪180‬‬\n\f      ‫مــرض نفســي واالبــن يحتــاج إلــى عنايــة حيــث إنــه مصــاب مبــرض احلــول‬\n      ‫كمــا أنــه أفــاد أنــه اصطلــح قبــل طالقهــا أن يكــون االبــن يف حضانتــه‬\n      ‫إذا أكمــل الســنة الســابعة‪ ،‬أنكــر املدعــي وكالــة مــرض موكلتــه‬\n      ‫النفســي وإهمالهــا لولدهــا‪ ،‬طلــب االبــن فحضــر يف اجللســة وحضــرت‬\n      ‫املدعيــة أصالــة فجــرى تخييــره بــن والــده ووالدتــه فاختــار البقــاء عنــد‬\n      ‫والــده‪ ،‬احلكــم بــرد دعــوى املدعيــة وإخــاء ســبيل املدعــى عليــه مــن‬\n      ‫هــذه الدعــوى‪ ،‬لــم تقنــع املدعيــة باحلكــم وطلبــت اســتئنافه بالئحــة‬\n      ‫اعتراضيــة فأجيبــت لطلبهــا وأفهمــت بتعليمــات االســتئناف‪ ،‬صــدق‬\n                                               ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض ففــي يــوم الثالثــاء املوافق‪1434/04/02‬ه ـ حضــر ‪........‬‬\n      ‫حامــل الســجل املدنــي رقــم ‪........‬بالوكالــة عــن ‪........‬حاملــة الســجل‬\n      ‫املدنــي رقــم ‪........‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫بشــرق الريــاض برقــم ‪........‬وتاريــخ ‪1433/12/26‬ه ـ والتــي تخولــه‬\n      ‫إقامــة الدعــاوى واملرافعــة واملدافعــة واإلقــرار واإلنــكار واملطالبــة‬\n      ‫بتنفيــذ األحــكام وقبــول األحــكام أو االعتــراض عليهــا وادعــى علــى‬\n      ‫احلاضــر معــه ‪........‬حامــل الســجل املدنــي رقــم ‪........‬قائــا يف دعــواه‬\n      ‫إن املدعــى عليــه كان زوجــا ملوكلتــي وقــد طلقهــا وســبق أن رزقــت‬\n      ‫منــه بابــن اســمه ‪........‬مولــود يف ‪1425/11/22‬ه ـ وقــد أخــذه املدعــى‬\n      ‫عليــه مــن موكلتــي وأطلــب احلكــم ملوكلتــي بحضانتــه هــذه دعــواي‬\n      ‫وباســتجواب املدعــى عليــه قــال مــا ذكــره املدعــي وكالــة مــن أننــي‬\n\n‫‪181‬‬\n\f‫كنــت زوجــا ملوكلتــه وأننــي طلقتهــا وســبق أن رزقــت منهــا بابــن اســمه‬\n‫‪........‬مولــود يف ‪1425/11/22‬ه ـ وإنــه عنــدي فصحيــح وال أوافــق علــى‬\n‫جعــل احلضانــة للمدعيــة ألنهــا تعانــي مــن مــرض نفســي وقــد أهملــت‬\n‫االبــن عندمــا كان عندهــا وهــو يعانــي مــن احلــول ويحتــاج إلــى مراجعات‬\n‫مســتمرة للمستشــفى للعــاج مــن ذلــك وأحتــاج أن يكــون عنــدي حتــى‬\n‫يســهل ذهابــي بــه للمستشــفى كمــا أننــي قبــل أن أطلــق املدعيــة قــد‬\n‫اصطلحــت معهــا علــى أن يكــون االبــن يف حضانتــي بعــد أن يكمــل‬\n‫الســنة الســابعة وال رغبــه للمحضــون يف االنتقــال إلــى والدتــه هكــذا‬\n‫أجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال مــا ذكــره املدعــى عليــه‬\n‫مــن أن موكلتــي مريضــة نفســيا وأنهــا أهملــت االبــن عندمــا كان‬\n‫عندهــا فغيــر صحيــح فطلبــت مــن املدعــى عليــه إحضــار ابنــه يف اجللســة‬\n‫القادمــة كمــا طلبــت مــن املدعــي وكالــة إحضــار موكلتــه يف اجللســة‬\n‫القادمــة ‪ .‬ويف يــوم األربعــاء املوافق‪1434/05/08‬ه ـ حضــرت املدعيــة‬\n‫أصالــة ‪........‬حاملــة الســجل املدنــي رقــم‪ ........‬واملعــرف بهــا مــن قبــل‬\n‫أخيهــا ‪........‬حامــل الســجل املدنــي رقم‪........‬كمــا حضــر املدعــي وكالة‬\n‫واملدعــى عليــه أصالــة وابــن املدعيــة واملدعــى عليــه ‪........‬فجــرى تخييــره‬\n‫بــن والــده ووالدتــه فاختــار البقــاء عنــد والــده فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة واختيــار احملضــون للبقــاء عنــد والــده وحلديــث أبــي‬\n‫هريــرة ‪-‬رضــي اهلل عنــه ‪ -‬أن امــرأة جــاءت إلــى رســول هلل صلــى اهلل‬\n‫عليــه وســلم فقالــت يــا رســول اهلل‪ :‬إن زوجــي يريــد أن يذهــب بابنــي وقــد‬\n‫ســقاني مــن بئــر أبــي عنبــة وقــد نفعنــي فقــال رســول اهلل صلــى اهلل عليــه‬\n‫وســلم‪ :‬اســتهما عليــه‪ .‬فقــال زوجهــا مــن يحاقنــي يف ولــدي فقــال النبــي‬\n‫صلــى اهلل عليــه وســلم (هــذا أبــوك وهــذه أمــك فخــذ بيــد أيهمــا شــئت‪.‬‬\n\n\n                                                                                        ‫‪182‬‬\n\f      ‫فأخــذ بيــد أمــه فانطلقــت بــه) رواه أبــو داود والنســائي‪ .‬لــذا فقــد رددت‬\n      ‫دعــوى املدعيــة وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى وبذلــك‬\n      ‫حكمــت وبعــرض احلكــم علــى املدعيــة قــررت عــدم القناعــة وطلبــت‬\n      ‫االســتئناف فأجبتهــا إلــى طلبهــا وقــررت تســليمها صــورة مــن صــك‬\n      ‫احلكــم حــاال لتقــدمي معارضتهــا عليــه خــال مــدة ال تتجــاوز ثالثــن يومــا‬\n      ‫فــإن تأخــرت عــن ذلــك ســقط حقهــا يف تقــدمي الالئحــة االعتراضيــة‬\n      ‫واكتســب احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/08‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يوم‬\n      ‫لدي‬\n       ‫االثنــن املوافــق ‪1434/08/08‬ه ـ افتتحــت اجللســة الســاعة الواحدة ّ‬\n      ‫أنــا ‪........‬القاضــي بهــذه احملكمــة خلف ـ ًا لفضيلــة الشــيخ ‪........‬النتقالــه‬\n      ‫مــن احملكمــة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف بالريــاض‬\n      ‫برقــم ‪ 341470623‬يف ‪1434/07/16‬ه ـ وقــد همــش علــى ظهــر الصــك‬\n      ‫مبــا نصــه ( تظهيــرات الدائــرة الثانيــة لألحــوال الشــخصية واالنهــاءات‬\n      ‫مبحكمــة االســتئناف بالريــاض ‪ ،‬احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا‬\n      ‫علــى هــذا الصــك رقــم ‪ 34209331‬وتاريــخ ‪1434/05/08‬ه ـ الصــادر‬\n      ‫مــن فضيلــة القاضــي يف احملكمــة الشــيخ ‪........‬وأصدرنــا القــرار‬\n      ‫رقــم ‪ 34258198‬وتاريــخ ‪1434/07/02‬ه ـ املتضمــن املصادقــة علــى‬\n      ‫احلكــم ‪ ،‬واهلل املوفــق ‪ .‬قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه قاضــي‬\n      ‫اســتئناف‪........‬ختمه وتوقيعــه رئيــس الدائــرة ‪........‬ختمــه وتوقيعــه)‬\n      ‫وأمــرت بالتهميــش بذلــك علــى ســجله‪ ،‬وكان ختــام هــذه اجللســة‬\n      ‫الســاعة الواحــدة والنصــف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                   ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/08/08‬ه ـ ‪.‬‬\n\n\n‫‪183‬‬\n\f‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض برقــم ‪ 34110682‬وتاريــخ ‪1434/6/14‬ه ـ املرفــق بهــا الصك‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪........ /‬املســجل برقــم‬\n‫‪ 34209331‬وتاريــخ ‪1434/5/8‬ه ـ اخلــاص بدعــوى ‪........ /‬ضــد‪........ /‬‬\n‫يف قضيــة حضانــة‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق‬\n                ‫وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪184‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":180,"source_page_end":184,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"471906a65e0c508a533531cec617cca69189ce30b790da746b9a181eccb7cb09","normalized_text_hash":"36c52a5ecd98b663773ed584be2443243a3ce0988b0e4b4834a07d85dd7319f9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p180-34209331"},{"id":"8ffe669b-186e-5fb3-8cb9-79ffb3895e64","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -مطالبة أب ملطلقته بحضانة ابنته التي جتاوزت سبع سنوات -رفض املدعى عليها طلب املدعي لصغر سن احملضونة وحلاجتها إلى من يقوم على رعايتها وألن األم األحق باحلضانة ما لم تتزوج -خير القاضي البنت بن والديها فاختارت أمها -احلكم بحضانة البنت للمدعى عليها.","document_number":"34258488","case_number":"3426001","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة الشيخ )","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/3","year":"1434","subject":"حضانة -مطالبة أب ملطلقته بحضانة ابنته التي جتاوزت سبع سنوات -رفض املدعى عليها طلب املدعي لصغر سن احملضونة وحلاجتها إلى من يقوم على رعايتها وألن األم األحق باحلضانة ما لم تتزوج -خير القاضي البنت بن والديها فاختارت أمها -احلكم بحضانة البنت للمدعى عليها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/3 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34258488 :‬‬\n                          ‫َر ْق ُم الدعوى‪3426001 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34309489‬تاريخه‪1434/8/30 :‬هـ‬\n\n\n      ‫حضانــة ‪ -‬مطالبــة أب ملطلقتــه بحضانــة ابنتــه التــي جتــاوزت ســبع‬\n      ‫ســنوات ‪ -‬رفــض املدعــى عليهــا طلــب املدعــي لصغــر ســن احملضونــة‬\n      ‫وحلاجتهــا إلــى مــن يقــوم علــى رعايتهــا وألن األم األحــق باحلضانــة مــا‬\n      ‫لــم تتــزوج ‪ -‬خيــر القاضــي البنــت بــن والديهــا فاختــارت أمهــا ‪ -‬احلكــم‬\n                                               ‫بحضانــة البنــت للمدعــى عليهــا‪.‬‬\n\n\n\n      ‫‪ .1‬قــال ابــن ا لقيــم رحمــه اهلل( فــاألم أحــق بــه مــن األب مــا لــم يقــم بهــا‬\n                                                               ‫إلــخ‪ ).....‬زاد املعــاد ‪436/5‬‬\n      ‫‪ .2‬قــال ابــن قدامــة رحمــه اهلل يف أحقيــة األم باحلضانــة (ال نعلــم أحــدا‬\n                                                    ‫خالفهــم) انتهــى املغنــى ‪. 413/11‬‬\n\n\n\n\n      ‫طالــب أب مطلقتــه بحضانــة ابنتــه التــي فــوق ســن الســابعة‪ ،‬رفضــت‬\n      ‫املدعــى عليهــا أم البنــت تســليم البنــت لصغــر ســنها وحاجتهــا ملــن يقــوم‬\n      ‫علــى رعايتهــا وذكــرت بــأن املدعــي مهمــل بالرعايــة كمــا أن املدعــي‬\n      ‫لــم ينفــق علــى ابنتــه رغــم صــدور حكــم قضائــي يلزمــه بذلــك‪ ،‬ســألت‬\n      ‫احملكمــة املدعــي عــن املدعــى عليهــا فلــم يقــدح بدينهــا وال بحضانتهــا‬\n      ‫وصــادق أنــه لــم ينفــق علــى ابنتــه رغــم صــدور حكــم مــن احملكمــة‬\n\n‫‪185‬‬\n\f‫يلزمــه بذلــك ودفــع بــأن املدعــى عليهــا لــم تطالــب بالتنفيــذ‪ ،‬خيــرت‬\n‫حملكمــة البنــت فاختــارت والدتهــا لــذا وملــا قــرره الفقهــاء مــن أن األم‬\n‫أحــق يف احلضانــة مــن األب إذا لــم تكــن متزوجــة ولــم يقــم بهــا مانــع‬\n‫فحكمــت احملكمــة بحضانــة البنــت موضــع النــزاع للمدعــى عليهــا‪،‬‬\n                                          ‫اعتــرض املدعــى‪ ،‬وصــدق احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬رئيــس محكمــة وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا برقــم وتاريــخ املقيــدة باحملكمــة برقــم وتاريــخ‬\n‫ففــي يــوم األربعــاء املوافــق ‪ 1434/01/28‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪08 : 30‬وفيهــا حضــر املدعــي وكالــة بصفتــه الوكيــل الشــرعي عــن‬\n‫(‪ ).....‬والتــي تخولــه إقامــة الدعــاوى نيابــة عــن والــده وحضــور اجللســات‬\n‫واإلقــرار واإلنــكار وطلــب األميــان وحضــرت حلضــوره املدعــى عليهــا‬\n‫برفقــة والدهــا املعــرف بهــا و بســؤال املدعــي وكالــة عــن دعــواه أجــاب‬\n‫قائــأ إن املدعــى عليهــا هــذه احلاضــرة معــي كانــت زوجــة لوالــدي‬\n‫موكلــي يف هــذه الدعــوى وقــد طلقهــا بتاريــخ ‪1428/7/7‬ه ـ ولــه منهــا‬\n‫ابنــة اســمها (‪ ).....‬وعمرهــا اآلن ســبع ســنوات أطلــب إلــزام املدعــى عليها‬\n‫بتســليم البنــت املذكــورة ملوكلــي واحلكــم لــه بحضانتهــا هــذه دعــواي‬\n‫وبعرضــه علــى املدعــى عليهــا أجابــت قائلــة مــا ذكــره املدعــي يف دعــواه‬\n‫مــن أن موكلــه كان زوجــا لــي وأنــه طلقنــي يف التاريــخ املذكــور ولــي‬\n‫منــه ابنــه عمرهــا ســبع ســنوات واســمها فهــذا صحيح وأمــا طلبه احلكم‬\n‫ملوكلــه بحضانــة ابنتــه فــا أوافــق علــى ذلــك ألنهــا الزالــت صغيــرة يف‬\n‫الســن وهــي بحاجــة إلــى مــن يقــوم علــى رعايتهــا ومصاحلهــا وال تســتطيع‬\n\n                                                                                   ‫‪186‬‬\n\f      ‫مفارقتــي وهــي منــذ أن علمــت أن والدهــا يريــد أخذهــا تبكــي ليــا‬\n      ‫ونهــارا وقــد أثــر ذلــك علــى صحتهــا وســلوكها والحــظ معلماتهــا يف‬\n      ‫املدرســة االضطرابــات الســلوكية التــي ظهــرت عليهــا بســبب خوفهــا‬\n      ‫مفارقتــي أرجــو مــن اهلل ثــم منكــم يــا فضيلــة الشــيخ أن ال تفــرق بينــي‬\n      ‫وبــن ابنتــي وأن تبقــى ابنتــي يف حضانتــي حتــى تكبــر هكــذا أجابــت‬\n      ‫بعــد ذلــك ســألت املدعــي وكالــة هــل تقــدح يف حضانــة املدعــى عليهــا‬\n      ‫البنتهــا بشــيء أو تتهمهــا بشــيء فأجــاب قائــا ال واهلل ال أقــول فيهــا إال‬\n      ‫خيــرا وهــي امــرأة صاحلــة لكــن موكلــي يريــد ضــم ابنتــه إلــى أخوانهــا‬\n      ‫وجمــع شــتات أبنائــه وبناتــه واالشــراف عليهــم بنفســه هكــذا أجــاب‬\n      ‫بعــد ذلــك جــرى رفــع اجللســة النتهــاء وقتهــا وحــددت لهــم موعــدا آخــر‬\n      ‫يــوم االثنــن ‪1434/3/23‬ه ـ وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/28‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬رئيــس محكمــة وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس محكمــة املقيــدة باحملكمــة‬\n      ‫برقــم وتاريــخ ففــي يــوم اإلثنــن املوافــق افتتحــت اجللســة الســاعة وفيهــا‬\n      ‫حضــر املدعــي وكالــة واملدعــى عليهــا وجــرى محاولــة اإلصــاح بــن‬\n      ‫الطرفــن إال أنــه تبــن أن وكالــة املدعــي ال تخولــه الصلــح فجــرى ســؤال‬\n      ‫املدعــى عليهــا عــن محــل إقامــة ابنتهــا فأجابــت قائلــة إنهــا تقيــم معــي يف‬\n      ‫بيــت والدتــي وال يســكن معهــا أحــد ســواي أنــا ووالدتــي هكــذا أجابــت‬\n      ‫بعــد ذلــك جــرى ســؤال املدعــى عليهــا عــن دراســة ابنتهــا املذكــورة‬\n      ‫فأجابــت قائلــة إنهــا تــدرس يف الصــف الثانــي االبتدائــي وهــي متفوقــة‬\n      ‫يف دراســتها ويوجــد لديهــا شــهادة تفــوق مــن مدرســتها هكــذا أجابــت‬\n      ‫وبعــرض ذلــك علــى املدعــي وكالــة قــال صحيــح إن البنــت تقيــم مــع‬\n\n\n‫‪187‬‬\n\f‫والدتهــا وجدتهــا يف بيتهــم اخلــاص هكــذا أجــاب فجــرى ســؤال املدعــى‬\n‫عليهــا عــن املانــع الــذي مينعهــا مــن تســليم البنــت لوالدهــا وهــل عليهــا‬\n‫ضــرر مــن ذلــك فأجابــت قائلــة إن بقــاء ابنتــي مــع والدهــا فيــه ضــرر‬\n‫عليهــا ألنــه يهملهــا كثيــرا وال يســأل عنهــا وهــو منــذ أن ولــدت لــم ينفــق‬\n‫عليهــا ريــاال واحــدا وقــد ســبق أن حكــم علــى والدهــا مببلــغ النفقــة‬\n‫منــذ والدتهــا إلــى حــن احلكــم الصــادر مــن محكمــة إال أنــه لــم يدفــع‬\n‫املبلــغ احملكــوم بــه وقــدرة أربعــة االف ومائــة وثمانيــة وخمســن ريــال‬\n‫وهــو قــاس جــد ًا يف تعاملــه وأخشــى أن تتعــرض ابنتــي لإلهمــال هكــذا‬\n‫ا مــا ذكرتــه املدعــى‬   ‫اجابــت وبعرضــه علــى املدعــي وكالــة أجــاب قائـ ً‬\n‫عليهــا مــن أنــى موكلــي قــاس يف تعاملــه وأنــه مهمــل ألطفالــه فهــذا غيــر‬\n‫صحيــح أمــا مــا ذكرتــه مــن النفقــة فــإن املدعــى عليهــا لديــه الصــك‬\n‫ـوم فيــه بالنفقــة املقــدرة شــرع ًا إال أن املدعــى عليهــا‬\n                                                           ‫املذكــور واحملكـ ً‬\n‫لــم تطلــب نفقــة ابنتهــا ولــم تطلــب تنفيــذ احلكــم وقــد أرســلني موكلــي‬\n‫عــدة مــرات لتســليم لنفقــة ابنتــه وأخــذ البنــت مــن والدتهــا إال أن والــد‬\n‫املدعــى عليهــا كان يرفــض اســتالم النفقــة ويرفــض تســليم البنــت‬\n‫ملوكلــي هكــذا أجــاب وبعرضــه علــى املدعــى عليهــا أجابــت قائلــة مــا‬\n‫ذكــره املدعــي وكالــه مــن أنــه قــد جانــي عــدة مــرات لتســليم النفقــة‬\n‫هــذا غيــر صحيــح وال أعلــم إن كان جــاء إلــى والــدي إال أنــه الــى اليــوم‬\n‫لــم ينفــق عليهــا وال يقــوم بزيارتهــا وذلــك لعــدة ســنوات هكــذا أجابــت‬\n‫ا مــا ذكرتــه املدعــى عليهــا‬    ‫وبعرضــه علــى املدعــي وكالــة أجــاب قائـ ً‬\n‫ليــس بصحيــح فموكلــي شــفيق علــى ابنتــه وال يهملهــا وال ميتنــع عــن‬\n‫زيارتهــا هكــذا أجــاب وبعــد ذلــك قــررت رفــع اجللســة إلنتهــاء وقتهــا‬\n‫وحــدد موعــد اجللســة القادمــة يــوم األحــد ‪1434/5/12‬ه ـ الســاعة‬\n\n\n                                                                                      ‫‪188‬‬\n\f      ‫التاســعة صباحـ ًا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                        ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/23‬ه‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس محكمــة ــففي يــوم اإلثنــن‬\n      ‫املوافــق‪1434/07/03‬ه افتتحــت اجللســة الســاعة احلاديــة عشــر صباحـ ًا‬\n      ‫وفيهــا حضــر املدعــي وكالــة وحضــر حلضــوره املدعــى عليهــا برفقــة‬\n      ‫والدهــا املعــرف بهــا وأحضــرت املدعيــة معهــا ابنتهــا وهــي تبلــغ مــن العمر‬\n      ‫ثمــان ســنوات وتــدرس يف الصــف الثانــي االبتدائــي مبدرســة االبتدائيــة‬\n      ‫فجــرى تخييرهــا بــن العيــش مــع والدهــا بــن أخوتهــا وأخواتهــا وبــن‬\n      ‫البقــاء مــع والدتهــا فاختــارت البقــاء مــع والدتهــا وأبــدت رفضهــا العيــش‬\n      ‫مــع والدهــا وإخوانهــا وقالــت بأنهــا ال تعــرف والدهــا فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة ومبــا أن املدعــي وكالــة يف اجللســات املاضيــة لــم‬\n      ‫يقــدح يف املدعــى عليهــا مبــا مينــع حضانتهــا البنتهــا وقــرر بأنــه ال يقــول يف‬\n      ‫املدعــى عليهــا إال خيــرا وأنهــا امــرأة صاحلــة وملــا قــرره الفقهــاء رحمهــم‬\n      ‫اهلل مــن أن األم هــي األحــق بحضانــة ولدهــا مــن األبقــال ابــن القيــم‬\n      ‫رحمــه اهلل « فــاألم أحــق بــه مــن األب مــا لــم يقــم بهــا مــا مينــع تقدميهــا‬\n      ‫أو بالولــد وصــف يقتضــي تخييــره‪ ،‬وهــذا مــا ال يعــرف فيــه نــزاع‪ ،‬وقــد‬\n      ‫قضــى بــه خليفــة رســول اهلل صلــى اهلل عليــه وســلم أبــو بكــر علــى عمــر‬\n      ‫بــن اخلطــاب فلــم ينكــر عليــه منكــر فلمــا ولــى عمــر قضــى مبثلــه» ‪.‬‬\n      ‫انتهــى مــن زاد املعــاد ‪ 436/5‬وهــو قــول فقهــاء املذاهــب األربعــة وغيرهــم‬\n      ‫قــال ابــن قدامــة رحمــه اهلل « ال نعلــم أحــدا خالفهــم « انتهــى املغنــي‬\n      ‫‪ 413/11‬لذلــك كلــه فقــد حكمــت بحضانــة الطفلــة (‪ ).....‬ابنــة‬\n      ‫املدعــي أصالــة ألمهــا املدعــى عليهــا وصرفــت النظــر عــن طلــب املدعــي‬\n      ‫هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه علــى الطرفــن قــررت املدعــى‬\n\n\n‫‪189‬‬\n\f‫عليهــا القناعــة باحلكــم وقــرر املدعــي وكالــة عــدم قناعتــه باحلكــم‬\n‫وطلــب متكينــه نســخة مــن احلكــم لتقــدمي االعتــراض عليــه فأجيــب‬\n‫لطلبــه وجــرى تســليمه نســخة مــن احلكــم يف نفــس اجللســة وأفهــم بــأن‬\n‫عليــه تقــدمي الالئحــة االعتراضيــة عليــه خــال ثالثــن يومــا مــن تاريــخ‬\n‫اليــوم وإال ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة وباهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n‫يف ‪1434/7/3‬هــ‪ .‬احلمــد هلل وحــده وبعــد فقــد عــادت إلينــا كامل أوراق‬\n‫املعاملــة مــن محكمــة االســتئناف بعســير وعليهــا قــرار دائــرة األحــوال‬\n‫الشــخصية رقــم ‪ 34309489‬يف ‪1434/8/30‬ه ـ املتضمــن أنــه بدراســة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n               ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/9/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة املختصة بتدقيق‬\n‫قضايــا األحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n‫مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة لهــذه‬\n‫احملكمــة مــن فضيلــة رئيــس احملكمــة العامــة الشــيخ‪ ).....(/‬املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلتــه برقــم‪ /‬وتاريــخ ‪1434/7/3‬ه ـ اخلاصــة‬\n‫بدعــوى ضــد بشــأن حضانــة علــى الصفــة املوضحــة بالصــك املتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون بباطنــه وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم مــع‬\n‫التنبيــه املرفــق ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n‫وســلم ‪ .‬دائــرة األحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت‬\n                                                                             ‫املــال‪.‬‬\n\n\n                                                                                        ‫‪190‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":185,"source_page_end":190,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"11deba8d4d4eabe5b3dfebc33a6f36d633690b97174c7d96eafc0d7ee3298bbc","normalized_text_hash":"0bc189a6161b42df5a0c1467d9f5310dc33e49267e0b378511406158bfb91cfb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p185-34258488"},{"id":"1fa3e81b-3a01-5166-ab43-c5e7dd30fb4f","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب حضانة بنت جتاوزت السابعة -عدم موافقة األم على حضانة األب -األم أحق باحلضانة حالة عدم زواجها وكون الرجل متزوج من عدة نساء -احلكم بحضانة األم البنتها -طلب احلضانة ملساومة األم على التنازل عن النفقة .","document_number":"34302025","case_number":"3427056","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة قلوة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/22","year":"1434","subject":"حضانة -طلب حضانة بنت جتاوزت السابعة -عدم موافقة األم على حضانة األب -األم أحق باحلضانة حالة عدم زواجها وكون الرجل متزوج من عدة نساء -احلكم بحضانة األم البنتها -طلب احلضانة ملساومة األم على التنازل عن النفقة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34302025 :‬تاريخه ‪1434/8/22 :‬هـ‬\n                           ‫رقم الدعوى ‪3427056:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34345663‬تاريخه‪1434/11/2 :‬هـ‬\n\n\n      ‫حضانــة ‪ -‬طلــب حضانــة بنــت جتــاوزت الســابعة ‪ -‬عــدم موافقــة األم‬\n      ‫علــى حضانــة األب ‪ -‬األم أحــق باحلضانــة حالــة عــدم زواجهــا وكــون‬\n      ‫الرجــل متــزوج مــن عــدة نســاء ‪ -‬احلكــم بحضانــة األم البنتهــا ‪ -‬طلــب‬\n                          ‫احلضانــة ملســاومة األم علــى التنــازل عــن النفقــة ‪.‬‬\n\n\n\n      ‫‪ .1‬قــال شــيخ اإلســام ‪ -‬رحمــه اهلل ‪ -‬يف مجمــوع الفتــاوى ( ‪)131/3.4‬‬\n      ‫( وأحمــد وأصحابــه إمنــا يقدمــون األب إذا لــم يكــن عليهــا يف ذلــك‬\n      ‫ضــرر ‪ ،‬فلــو قــدر أنــه عاجــز عــن حفظهــا وصيانتهــا أو مهمــل حلفظهــا‬\n      ‫وصيانتهــا ‪ ،‬فإنــه تقــدم األم يف هــذه احلالــة‪ ،‬فكل ما قدمناه من األبوين‬\n      ‫إمنــا نقدمــه إذا حصــل بــه مصلحتهــا أو اندفعــت بــه مفســدتها‪ ،‬فأمــا‬\n                             ‫مــع وجــود فســاد أمرهــا ‪ ،‬فاآلخــر أولــى بــا ريــب )‪.‬‬\n      ‫‪ .2‬وقال ‪ -‬رحمه اهلل ‪ -‬يف مواضع آخر يف مجموع الفتاوى ‪:)132/34( :‬‬\n      ‫«ولــذا لــو قــدر أن األب تــزوج ضــرة وهــي تتــرك عنــد ضــرة أمهــا ال تعمــل‬\n      ‫مصلحتهــا بــل تؤذيهــا أو تقصــر يف مصلحتهــا ‪ ،‬وأمهــا تعمــل ملصلحتها‬\n                                                  ‫وال تؤذيهــا فاحلضانــة هنــا لألم»‪.‬‬\n\n\n\n\n‫‪191‬‬\n\f‫حضــر املدعــي وذكــر أن املدعــى عليهــا كانــت زوجــة لــه وأجنبــت‬\n‫منــه علــى فــراش الزوجيــة بنتــن وطلــب حضانــة بنتــه ‪ .......‬املولــودة‬\n‫بتاريــخ ‪1426/6/20‬ه ـ حيــث إنهــا بلغــت ســبع ســنني‪ ،‬بعــرض دعــوى‬\n‫املدعــي علــى املدعــى عليهــا صادقــت علــى مــا ذكــره املدعــي مــن كونــه‬\n‫زوجـ ًا لهــا ســابق ًا وإجنــاب البنتــن منــه وهــي غيــر متنازلــة عــن حضانتهــا‬\n‫البنتهــا‪ .......‬كــون املدعــي متــزوج مــن أربــع نســوة ‪ -‬قــرر املدعــي أن‬\n‫املدعــى عليهــا غيــر متزوجــة ‪ -‬بعــرض الصلــح علــى الطرفــن أبــدى‬\n‫املدعــي اســتعداده للصلــح مــع املــرأة والتنــازل عــن حضانــة البنــت إذا‬\n‫تنازلــت املدعــى عليهــا عــن نفقتهــا ورفضــت املدعــي عليهــا هــذا الصلــح‪،‬‬\n‫ظهــر للقاضــي مــن مجريــات القضيــة أن هــدف املدعــي هــو إســقاط‬\n‫النفقــة عــن ابنتــه وعــدم حتملــه‪ ،‬احلكــم بحضانــة ‪ .......‬ألمهــا املدعــي‬\n‫عليهــا‪ ،‬قــرر املدعــي اعتراضــه احلكــم بالئحــة اعتراضيــة ‪ -‬صــدق‬\n                                        ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ .......‬القاضــي يف احملكمــة العامــة مبحافظــة قلــوة وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n‫قلــوة برقــم ‪ 3427056‬وتاريــخ ‪1434/01/17‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 34131510‬وتاريــخ ‪1434/01/17‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق‪ 1434/07/30‬ه ـ افتتحــت اجللســة وفيهــا حضــر ‪ .......‬ســعودي‬\n\n                                                                                       ‫‪192‬‬\n\f      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬وحضــر حلضــوره‪.......‬‬\n      ‫ســعودي مبوجــب الســجل املدنــي رقــم ‪ .......‬بصفتــه وكيــل عــن املدعــى‬\n      ‫عليهــا ‪ .......‬وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n      ‫قلــوة برقــم ‪ .......‬وتاريــخ ‪1433/3/26‬ه ـ وحيــث إن وكالــة املدعــى‬\n      ‫عليــه احلاضــر ال تخولــه املرافعــة واملدافعــة واالقــرار واالنــكار وقبــول‬\n      ‫األحــكام واإلعتــراض عليهــا لــذا فقــد طلبــت مــن املدعــى عليــه وكالــة‬\n      ‫تغييــر وكالتــه أو إحضــار موكلتــه يف اجللســة القادمــة وعليــه رفعــت‬\n      ‫اجللســة ويف جلســة أخــرى حضــر املدعــي ولــم حتضــر املدعــى عليهــا‬\n      ‫وال وكيــل عنهــا رغــم تبلــغ وكيلهــا باملوعــد كمــا لــم يحــرر املدعــي‬\n      ‫دعــواه وطلــب مهلــة لتحريــر الدعــوى وإلعــادة إبــاغ املدعــى عليهــا رفعــت‬\n      ‫اجللســة ويف جلســة اخــرى حضــر املدعــي ‪ .......‬املــدون هويتــه ســابق ًا‬\n      ‫وحضــر حلضــوره ‪ ....... .......‬ســعودي بالســجل املدنــي رقــم ‪ .......‬بصفتــه‬\n      ‫ا عــن املدعــى عليهــا ‪ ....... .......‬ســعودية بالســجل املدنــي‬       ‫وكي ـ ً‬\n      ‫رقــم ‪ .......‬مبوجــب الوكالــة رقــم ‪ 341036271‬وتاريــخ ‪1434/8/1‬ه ـ‬\n      ‫املخولــة لــه حــق املرافعــة واملدافعــة والصلــح والتنــازل وقبــول االحــكام‬\n      ‫ا املدعــي‬  ‫ونفيهــا واالعتــراض علــى االحــكام وطلــب االســتئناف قائ ـ ً‬\n      ‫يف دعــواه أننــي تزوجــت املدعــى عليهــا ‪ .......‬واجنبــت منهــا طفلتــن همــا‬\n      ‫‪ .......‬املولــودة يف ‪1426/6/20‬ه ـ ‪ .......‬املولــودة يف ‪1432/2/3‬ه ـ ومــن‬\n      ‫ثــم طلقتهــا يف ‪1432/12/23‬ه ـ وحيــث ان ابنتــي ‪ .......‬بلغت ســبع ســنني‬\n      ‫وزيــادة أطلــب احلكــم لــي بحضانتهــا والــزام املدعــى عليهــا بتســليمها‬\n      ‫لــي هــذه دعــواي وبعــرض ماجــاء يف دعــوى املدعــي علــى املدعــى عليــه‬\n      ‫ا صحيــح ماذكــره مــن الــزواج واجنــاب الطفلتــن‬        ‫وكالــة اجــاب قائ ـ ً‬\n      ‫والطــاق يف التاريــخ املذكــور وامــا فيمــا يخــص حضانــة ابنتــه ‪.......‬‬\n\n\n‫‪193‬‬\n\f‫فــإن موكلتــي غيــر متنازلــة عــن حضانتهــا إلبنتهــا ‪ .......‬كــون املدعــي‬\n‫‪ .......‬املذكــور متــزوج وعلــى ذمتــه اربــع نســاء فكيــف يقــوم برعايتهــا‬\n‫واحملافظــة عليهــا فهــذا امــر يســتحيل أمــا موكلتــي فمســتعدة برعايتهــا‬\n‫وحفــظ شــؤونها كونهــا غيــر متزوجــة‪ ،‬وبســؤال املدعــي هــل صحيــح‬\n‫أنــه متــزوج وعلــى ذمتــه أربــع نســاء وهــل صحيــح أن مطلقتــه غيــر‬\n‫متزوجــه قــال صحيــح أنــي متــزوج بأربــع وهــذا ال مينعنــي مــن حضانــة‬\n‫إبنتــي كمــا انــه صحيــح أن طليقتــي املدعــى عليهــا غيــر متزوجــه فجــرى‬\n‫عــرض الصلــح بــن الطرفــن فقــال املدعــي أنــا مســتعد بالتنــازل عــن‬\n‫حضانــة إبنتــي مقابــل تنــازل والدتهــا عــن النفقــة ورعايتهــا وحفظهــا‬\n‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ان موكلتــي ترفــض ذلــك‬\n                              ‫وهــي ال ترغــب يف التنــازل عــن حضانــة إبنتهــا‬\n‫فبنــاء ًعلــى ماســبق وحيــث اتضــح لنــا مــن مجريــات القضيــة ان‬\n‫ـاء‬\n‫هــدف املدعــي هــو إســقاط النفقــة عــن ابنتــه وعــدم حتملــه لهــا وبنـ ً‬\n‫علــى ماذكــره شــيخ االســام يف مجمــوع الفتــاوى‪ « 131/34‬واحمــد‬\n‫واصحابــة إمنــا يقدمــون األب اذا لــم يكــن عليهــا يف ذلــك ضــرر فلــو‬\n‫قــدر أنــه عاجــز عــن حفظهــا وصيانتهــا أو مهمــل حلفظهــا وصيانتهــا فإنــه‬\n‫يقــدم االم يف هــذه احلالة‪،‬فــكل ماقدمنــاه مــن االبويــن إمنــا نقدمــه اذا‬\n‫حصــل بــه مصلحتهــا أو اندفعــت بــه مفســدتها‪ ،‬فأمــا مــع وجــود فســاد‬\n‫امرهــا مــع احدهمــا فاالخــر اولــى بهــا بــا ريــب « وقــال رحمــه اهلل يف‬\n‫مجمــوع الفتــاوى ‪ »132/34‬وإذا قــدر أن االب تــزوج ضــرة وهــي تتــرك‬\n‫عنــد ضــرة امهــا ال تعمــل مصلحتهــا بــل تؤذيهــا أو تقصــر يف مصلحتهــا‬\n‫وامهــا تعمــل مصلحتهــا وال تؤذيهــا فاحلضانــة هنــا لــأم « واحلالــة لدينــا‬\n‫أن املدعــي متــزوج بأربــع ‪ ،‬وأمهــا مســتعدة برعايتهــا الرعايــة الســليمه‬\n\n\n                                                                                   ‫‪194‬‬\n\f      ‫الصحيحــة وغيــر متزوجــة ‪ ،‬عليــه فقــد حكمــت بحضانــة ‪ .......‬ألمهــا‬\n      ‫‪ ، .......‬وبعــرض ذلــك علــى الطرفــن قــرر املدعــي عــدم القناعــة وطلــب‬\n      ‫نســخة مــن احلكــم لالعتــراض عليــه وافهــم باحلضــور يــوم غــد ًا االثنــن‬\n      ‫املوافــق ‪1434/8/22‬ه ـ الســتالم نســخة مــن احلكــم واالعتــراض عليــه‬\n      ‫خــال ثالثــن يوم ـ ًا مــن تاريخــه وتقــدمي الئحتــه االعتراضيــة إن رغــب‬\n      ‫واال ســقط حقــه يف اســتئناف احلكــم وقــرر املدعــى عليــه وكالــة‬\n      ‫قناعتــه باحلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                  ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/21‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n      ‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبحافظــة قلــوة برقــم ‪ 34131510‬وتاريــخ ‪1434/10/20‬ه ـ‬\n      ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ .......‬القاضي باحملكمة‬\n      ‫العامــة مبحافظــة قلــوه برقــم ‪ 34302025‬وتاريــخ ‪1434/8/22‬ه ـ ‪،‬‬\n      ‫املتضمــن دعــوى ‪ .......‬ضــد املــرأة ‪ .......‬يف حضانــة‪ ،‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة ‪ ،‬تقــررت املوافقــة علــى احلكــم ‪،‬‬\n      ‫واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪،‬‬\n\n\n\n\n‫‪195‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":191,"source_page_end":195,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"541eb888fd61ea26325bf83e21997c3eb161b02f51fe08506d4f68f0b028db7b","normalized_text_hash":"86bbb13affdaa11cb881a3cdf489d8e4ab8102df58621473ed932fc65120e7d1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p191-34302025"},{"id":"8a5c09a7-88ff-5635-b732-f11c4787aae2","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب حضانة بنات -تغيب املدعى عليه وسفره خارج الباد -األم غالب ا محل األمان والرعاية والتربية -ثبوت غياب املدعى عليه بشهادة الشهود واجلهات الرسمية -الزوجية غير قائمة -احلكم بحضانة البنات ألمهن.","document_number":"34354960","case_number":"3433849","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/9","year":"1434","subject":"حضانة -طلب حضانة بنات -تغيب املدعى عليه وسفره خارج الباد -األم غالب ا محل األمان والرعاية والتربية -ثبوت غياب املدعى عليه بشهادة الشهود واجلهات الرسمية -الزوجية غير قائمة -احلكم بحضانة البنات ألمهن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34354960 :‬تاريخه ‪1434/11/9 :‬هـ‬\n                           ‫رقم الدعوى ‪3433849:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34354960‬تاريخه‪1434/1/25 :‬هـ‬\n\n\n      ‫حضانــة‪ -‬طلــب حضانــة بنــات‪ -‬تغيــب املدعــى عليــه وســفره خــارج‬\n      ‫البــاد‪ -‬األم غالب ـ ًا محــل األمــان والرعايــة والتربيــة‪ -‬ثبــوت غيــاب‬\n      ‫املدعــى عليــه بشــهادة الشــهود واجلهــات الرســمية‪ -‬الزوجيــة غيــر‬\n                                ‫قائمــة ‪ -‬احلكــم بحضانــة البنــات ألمهــن‪.‬‬\n\n\n\n      ‫‪ .1‬مــا رواه اإلمــام أحمــد وأبــو داود وصححــه احلاكــم مــن حديــث عبــد‬\n      ‫اهلل بــن عمــر رضــي اهلل عنهمــا ( أن امــرأة قالــت ‪ :‬يــا رســول اهلل ‪ :‬إن ابنــي‬\n      ‫هــذا كان بطنــي لــه وعــاء ‪ ،‬وثديــي لــه ســقاء ‪ ،‬وحجــري لــه حــواء ‪ ،‬وإن‬\n      ‫أبــاه طلقنــي وأراد أن ينزعــه منــي فقــال ‪ :‬أنــت أحــق بــه مــا لــم تنكحــي )‬\n                                              ‫‪ .2‬القاعدة الفقهية ‪ ( :‬الضرر يزال ) ‪.‬‬\n                                         ‫‪ .3‬القاعدة الفقهية ( ال ضرر وال ضرار ) ‪.‬‬\n\n\n\n      ‫ادعــت املدعيــة علــى الغائــب عــن مجلــس احلكــم بأنــه كان زوج ـ ًا‬\n      ‫لهــا وأجنبــت منــه علــى فــراش الزوجيــة بنتــن وهمــا ‪ ......‬وعمرهــا (‪12‬‬\n      ‫ســنة)‪ ...... ،‬وعمرهــا ( تســع ســنوات ) واملدعــى عليــه متغيــب ومســافر‬\n      ‫عــن البلــد منــذ ســت ســنوات وقــد طلقــت منــه مبوجــب صــك شــرعي‬\n      ‫وتطلــب حضانــة أوالدهــا ورعايتهــم وتولــي شــؤونهم‪ ،‬مت البحــث عــن‬\n\n‫‪203‬‬\n\f‫املدعــى عليــه والتحــري وتبــن أنــه لــم يعثــر عليــه‪ ،‬ثبــت مــن خــال برنــت‬\n‫اجلــوازات مغــادرة املدعــى عليــه مغــادرة نهائيــة قبــل ســت ســنوات وبنــاء‬\n‫عليــه مت فســخ نكاحهــا منــه وقــد شــهد بذلــك الشــهود املعدلون شــرعاً‪،‬‬\n‫قــررت احملكمــة احلكــم بحضانــة البنــات لوالدتهــن املدعيــة ورعايتهــم‬\n‫وتولــي شــؤونهم الدينيــة والدنيويــة‪ ،‬بعــث املعاملــة حملكمــة االســتئناف‬\n         ‫حســب التعليمــات‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ ..........‬القاضــي باحملكمــة العامــة مبحافظــة جــدة‪ ،‬وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n‫جــدة برقــم ‪ 3433849‬وتاريــخ ‪1434/01/19‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 34163055‬وتاريــخ ‪ 1434/01/19‬ه ـ ويف يــوم الســبت‬\n‫املوافق‪ 1434/07/15‬هـ افتتحت اجللسة الساعة ‪ 08 : 30‬وفيها حضر‬\n‫املدعــي وكالــة ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫بوكالتــه عــن رقــم ‪ 11747‬يف ‪1433/03/13‬ه ـ اجللــد ‪ 3753‬الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة بجنــوب جــدة التــي تخــول لــه حــق املرافعــة‬\n‫واملدافعــة عــن موكلتــه املذكــورة ولــم يحضــر املدعــى عليــه ووردتنــا‬\n‫االفــادة مــن مديــر شــرطة جــدة بخطابــه رقــم ‪ 25/1/20/4861‬وتاريــخ‬\n‫‪1434/06/11‬ه ـ املتضمــن انــه مت البحــث والتحــري عــن املذكــور ولــم‬\n‫يتــم العثــور عليــه وباالستفســار عنــه باحلاســب اآللــي طرفنــا بأنــه اتضــح‬\n‫بأنــه يعمــل حتــت كفالــة املدعيــة وقــد مت االتصــال علــى جوالــه املــدون‬\n‫بالبرنــت أكثــر مــن مــره واتضــح بأنــه مغلــق ومــا زال البحــث جــاري ‪.‬‬\n\n                                                                                     ‫‪204‬‬\n\f      ‫واســتنادا الى املادة ‪ 55‬فقد قررت رفع اجللســة لتبليغ املدعى عليه للمرة‬\n      ‫الثانيــة ‪ .‬ويف جلســة أخــرى يف يــوم األربعــاء املوافــق ‪1434/10/28‬ه ـ‬\n      ‫افتتحت اجللسة الساعة ‪ 10 : 15‬وفيها حضرت املدعية أص ــالة سعودية‬\n      ‫اجلنســية مبوجــب الــسجـ ــل املدنــي رقـ ـ ـ ــم واملعــرف بهــا مــن قبـ ـ ــل أخيهــا‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وحضــر املدعــي‬\n      ‫وكالــة املرصــود وكالتــه يف اجللســة الســابقة ‪ ،‬ولــم يحضــر املدعــى‬\n      ‫عليــه وال مــن ينــوب عنــه ‪ .‬وبســؤال املدعيــة عــن دعواهــا أدعــت قائلــة ‪ :‬أن‬\n      ‫املدعــى عليــه كان زوجـ ًا لــي وأجنبــت منــه علــى فــراش الزوجيــة ابنتــان‬\n      ‫همــا ‪ .......‬وعمرهــا ‪ 12‬اثنــى عشــر ســنة و‪ .......‬وعمرهــا ‪ 9‬تســع ســنوات‪،‬‬\n      ‫وقــد تطلقــت منــه مبوجــب الصــك الصــادر مــن مكتــب فضيلتكــم‬\n      ‫برقــم ‪ 249015111279320013‬وتاريــخ ‪1432/01/23‬ه ـ وهــو متغيــب‬\n      ‫ومســافر عــن البلــد منــذ ســت ســنوات تقريب ـ ًا وقــد جــرى إثبــات ذلــك‬\n      ‫لــدى فضيلتكــم يف الصــك املشــار لــه بعاليــه‪ ،‬لــذا أطلــب حضانــة‬\n      ‫أوالدي ورعايتهــم وتولــي شــئونهم ‪ .‬هــذه دعــواي ‪ .‬ثــم جــرى منــا اإلطــاع‬\n      ‫علــى الصــك رقــم ‪ 49015111279320013‬وتاريــخ ‪1432/01/23‬ه ـ‬\n      ‫واملصــدق مــن محكمــة اإلســتئناف مبكــة املكرمــة بالقــرار رقــم‬\n      ‫‪ 33341855‬وتاريــخ ‪1433/07/15‬ه ـ واملتضمــن جــواب مديــر جــوازات‬\n      ‫مكــة املكرمــة بخطابــه رقــم ‪ 31/57843‬وتاريــخ ‪1431/06/18‬ه ـ‬\n      ‫اجلوابــي للخطــاب رقــم ‪ 31/51288‬وتاريــخ ‪1431/05/28‬ه ـ املتضمــن‬\n      ‫مغــادرة املدعــى عليــه عــن اململكــة مغــادرة نهائيــة يف ‪1427/12/24‬ه ـ‬\n      ‫واملتضمــن كذلــك شــهادة الشــهود املعدلــن شــرع ًا علــى تغيــب املدعــى‬\n      ‫عليــه منــذ ســت ســنوات ‪ .‬ثــم جــرى منــا ســؤال املدعية ‪ :‬هل أنتــي متزوجة‬\n                                                                        ‫اآلن ؟ فأجابــت ‪ :‬ال ‪.‬‬\n\n\n‫‪205‬‬\n\f‫وبنــاء علــى مــا تقــدم مــن الدعــوى وملــا جــاء مــن بينــات يف الصــك الصــادر‬\n‫منــا برقــم ‪ 49015111279320013‬وتاريــخ ‪1432/01/23‬ه ـ علــى‬\n‫تغيــب املدعــى عليــه وخروجــه مــن اململكــة العربيــة الســعودية خروج ـ ًا‬\n‫نهائي ـ ًا ‪ ،‬وملــا يف تــرك األوالد بــا مســؤول واحلالــة مــا ذكــر ضــرر ًا‬\n‫عليهــم يف دينهــم ودنياهــم ‪ ،‬وللقاعــدة الفقهيــة الكليــة أن الضــرر يــزال‬\n‫وللقاعــدة الفقهيــة أن ال ضــرر وال ضــرار وألن األم يف الغالــب محــل‬\n‫األمــان والرعايــة والتربيــة ألوالدهــا ‪ ،‬ومراعــاة منــا ملصلحــة احملضــون‬\n‫وملــا ثبــت يف الســنة عنــد اإلمــام أحمــد وأبــو داود وصححــه احلاكــم مــن‬\n‫حديــث عبــداهلل بــن عمــر رضــي اهلل عنهمــا (( أن امــرأة قالــت‪ :‬يــا رســول‬\n‫اهلل ‪ :‬إن ابنــي هــذا كان بطنــي لــه وعــاء ‪ ،‬وثديــي لــه ســقاء ‪ ،‬وحجــري‬\n‫لــه حــواء ‪ ،‬وإن أبــاه طلقنــي وأراد أن ينزعــه منــي فقــال ‪ :‬أنــت أحــق بــه مــا‬\n‫لــم تنكحــي )) ‪ .‬لــكل ذلــك فقــد ثبــت لــدي اســتحقاق املدعيــة حلضانــة‬\n‫أوالدهــا مــن املدعــى عليــه ورعايتهــم وتولــي شــئونهم الدينيــة والدنيويــة‬\n‫وبذلــك حكمــت ‪ .‬وســيتم بعــث املعاملــة حملكمــة اإلســتئناف مبكــة‬\n‫املكرمــة حســب التعليمــات ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/10/28‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n‫نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال يف محكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلينــا شــفع خطــاب‬\n‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة رقــم ‪34163055‬‬\n‫وتاريــخ ‪1435/1/16‬ه ـ املشــتملة علــى الصــك رقــم ‪ 34354960‬وتاريــخ‬\n‫‪1434/11/9‬ه ـ الصــادر مــن فضيلة الشــيخ القاضي باحملكمة الـ ــعامة‬\n\n\n                                                                                         ‫‪206‬‬\n\f      ‫مبحافظــة جــدة املتضمــن دعــوى ‪ .......‬ضــد ‪ .......‬يف حضانــة وبدراســة‬\n      ‫الصــك وصــورة ضبطــه تقــرر املوافقــة علــى احلكــم مــع التنبيــه املرفــق‬\n      ‫والغائــب علــى حجتــه ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                         ‫وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":203,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9228f38c425985790f260e5c646372df03fa69d6e8aebcb8108f5b62a358c06c","normalized_text_hash":"d9e3cea143396153ef27fc57e2490de88d24320bac6c21a35070f4e3f93ddad2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p203-34354960"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

